-- ============================================================
-- 20261118000800 -- STT stabilization REPAIR (forward-only, idempotent). GENERATED by supabase/tools/build_0800.sh -- do not edit.
--
-- For installations that already applied an earlier version of 20261118000500/0600/0700 (which their tooling will not run again),
-- and harmless on a database that is already current. It
--   1. refuses unless the 0700 marker exists,
--   2. re-asserts the FINAL definition of everything in 0500, 0600 and 0700 (verbatim copies below; includes DROP of the obsolete
--      secret-less stt_* overloads that CREATE OR REPLACE would otherwise leave callable by any project member),
--   3. repairs data left behind by the earlier version (attempt rows, deletion deadlines, ledger certainty),
--   4. records marker 20261118000800_stt_stabilization_repair.
-- Fresh databases (0400 -> 0500 -> 0600 -> 0700) do not need this file but may apply it.
-- ============================================================
DO $$
BEGIN
    IF to_regclass('public.clearspace_migrations') IS NULL
       OR NOT EXISTS (SELECT 1 FROM public.clearspace_migrations WHERE version = '20261118000700_meeting_audio') THEN
        RAISE EXCEPTION 'Preflight failed -- apply 20261118000700_meeting_audio first (this file repairs an installation that has it). Nothing was changed.';
    END IF;
END $$;

-- ################################################################
-- ## verbatim copy of 20261118000500_intelligence_core.sql
-- ################################################################
-- ============================================================
-- 20261118000500 -- Intelligence core: meetings, transcripts, AI runs, intelligence items
--
-- Implements docs/intelligence/ARCHITECTURE.md §9 for Project Intelligence 2.0 + Meeting Intelligence (text MVP).
-- Purely ADDITIVE: new tables and functions only. No existing table, policy, function or row is changed or deleted.
-- Idempotent (IF NOT EXISTS / CREATE OR REPLACE / DROP POLICY IF EXISTS). Apply after 20261117000400.
--
-- Design
--  * Authorization reuses the existing model: every row carries `project_id TEXT` and access is
--    `is_project_member(project_id)` (SELECT / write) or `is_project_owner` (delete of foreign meetings).
--  * Composite foreign keys (meeting_id, project_id) make it IMPOSSIBLE for a transcript, run or item to point at a
--    meeting of another project.
--  * AI output enters ONLY through SECURITY DEFINER RPCs that check membership explicitly, validate evidence against
--    the stored transcript and write one run + its items in ONE transaction (all or nothing). Authenticated users have
--    no INSERT privilege on runs/items.
--  * Review / apply / undo are SECURITY INVOKER (RLS keeps applying to cards, comments, activity logs) and are guarded
--    by a state-machine trigger, so even a direct UPDATE cannot skip a state or forge an applied card.
--  * Nothing here calls an AI provider or stores an API key.
-- ============================================================

-- Preflight: refuse early and precisely instead of failing half-way.
DO $$
DECLARE
    v_missing TEXT := '';
    c TEXT;
BEGIN
    IF to_regclass('public.clearspace_migrations') IS NULL THEN
        v_missing := v_missing || ' migration:20261117000100_security_foundation(apply it first)';
    ELSIF NOT EXISTS (SELECT 1 FROM public.clearspace_migrations WHERE version = '20261117000100_security_foundation') THEN
        v_missing := v_missing || ' migration:20261117000100_security_foundation(apply it first)';
    END IF;
    IF to_regprocedure('public.is_project_member(text)') IS NULL THEN v_missing := v_missing || ' fn:is_project_member'; END IF;
    IF to_regprocedure('public.is_project_owner(text)') IS NULL THEN v_missing := v_missing || ' fn:is_project_owner'; END IF;
    IF to_regclass('public.ai_requests') IS NULL THEN v_missing := v_missing || ' table:ai_requests'; END IF;
    FOREACH c IN ARRAY ARRAY[
        'projects.id', 'columns.id', 'columns.project_id', 'columns.position',
        'cards.id', 'cards.column_id', 'cards.title', 'cards.details', 'cards.due_date', 'cards.position',
        'cards.archived', 'cards.updated_at', 'cards.assignee_name', 'cards.assignee_initials', 'cards.assignee_color',
        'task_comments.id', 'task_comments.card_id', 'task_comments.author_name', 'task_comments.content',
        'card_assignees.card_id', 'card_assignees.member_id', 'card_assignees.position',
        'activity_logs.id', 'activity_logs.project_id', 'activity_logs.card_id', 'activity_logs.actor_id',
        'activity_logs.actor_name', 'activity_logs.action_type', 'activity_logs.entity_type', 'activity_logs.details',
        'workspace_members.id', 'workspace_members.full_name', 'workspace_members.initials',
        'workspace_members.avatar_color', 'profiles.id', 'profiles.email', 'profiles.display_name']
    LOOP
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                       WHERE table_schema = 'public' AND table_name = split_part(c, '.', 1)
                         AND column_name = split_part(c, '.', 2)) THEN
            v_missing := v_missing || ' col:' || c;
        END IF;
    END LOOP;
    IF v_missing <> '' THEN
        RAISE EXCEPTION 'Preflight failed -- intelligence core cannot be installed. Missing:%. Nothing was changed.', v_missing;
    END IF;
END $$;

-- ------------------------------------------------------------
-- 0. Helpers
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.touch_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.touch_updated_at() FROM PUBLIC, anon, authenticated;

-- Strict YYYY-MM-DD parser: returns NULL for anything that is not a real calendar date (no cast errors leak out).
CREATE OR REPLACE FUNCTION public.iso_date_or_null(p TEXT)
RETURNS DATE
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_temp
AS $$
BEGIN
    IF p IS NULL OR p !~ '^\d{4}-\d{2}-\d{2}$' THEN RETURN NULL; END IF;
    RETURN p::date;
EXCEPTION WHEN others THEN
    RETURN NULL;
END;
$$;
REVOKE ALL ON FUNCTION public.iso_date_or_null(TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.iso_date_or_null(TEXT) TO authenticated;

-- Folding for evidence checks done by the DATABASE (mirror of FOLD_SPEC in src/lib/intelligence/fold.ts for Latin scripts:
-- strip diacritics, lowercase, every run of non-alphanumerics = one space). Other scripts keep their letters (lowercased).
CREATE OR REPLACE FUNCTION public.fold_text(p TEXT)
RETURNS TEXT
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_temp
AS $$
    SELECT btrim(regexp_replace(lower(translate(coalesce(p, ''), 'ÀÁÂÃÄÅÇÈÉÊËÌÍÎÏÑÒÓÔÕÖÙÚÛÜÝàáâãäåçèéêëìíîïñòóôõöùúûüýÿĀāĂăĄąĆćĈĉĊċČčĎďĒēĔĕĖėĘęĚěĜĝĞğĠġĢģĤĥĨĩĪīĬĭĮįİĴĵĶķĹĺĻļĽľŃńŅņŇňŌōŎŏŐőŔŕŖŗŘřŚśŜŝŞşŠšŢţŤťŨũŪūŬŭŮůŰűŲųŴŵŶŷŸŹźŻżŽžĐđŁłØøĦħ', 'AAAAAACEEEEIIIINOOOOOUUUUYaaaaaaceeeeiiiinooooouuuuyyAaAaAaCcCcCcCcDdEeEeEeEeEeGgGgGgGgHhIiIiIiIiIJjKkLlLlLlNnNnNnOoOoOoRrRrRrSsSsSsSsTtTtUuUuUuUuUuUuWwYyYZzZzZzDdLlOoHh')), '[^[:alnum:]]+', ' ', 'g'));
$$;
GRANT EXECUTE ON FUNCTION public.fold_text(TEXT) TO authenticated;

-- Is the quote contained in the text as WHOLE WORDS, its "..." parts in order, with >= 6 letters and >= 2 words?
-- (same rule as quoteSupported in src/lib/intelligence/evidence.ts). Used to recompute `quoteFound` so that a client can
-- never claim a verified quote the transcript does not contain.
CREATE OR REPLACE FUNCTION public.quote_in_text(p_quote TEXT, p_text TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public, pg_temp
AS $$
DECLARE
    v_parts TEXT[];
    v_part TEXT;
    v_hay TEXT := ' ' || public.fold_text(p_text) || ' ';
    v_joined TEXT := '';
    v_pos INTEGER := 1;
    v_idx INTEGER;
BEGIN
    IF p_quote IS NULL OR btrim(p_quote) = '' THEN RETURN FALSE; END IF;
    v_parts := regexp_split_to_array(p_quote, '…|\.\.\.');
    FOREACH v_part IN ARRAY v_parts LOOP
        v_part := public.fold_text(v_part);
        IF v_part = '' THEN CONTINUE; END IF;
        v_joined := btrim(v_joined || ' ' || v_part);
        v_idx := position(' ' || v_part || ' ' IN substr(v_hay, v_pos));
        IF v_idx = 0 THEN RETURN FALSE; END IF;
        v_pos := v_pos + v_idx - 1 + char_length(v_part) + 1; -- the trailing space stays available for the next part
    END LOOP;
    IF v_joined = '' THEN RETURN FALSE; END IF;
    RETURN char_length(regexp_replace(v_joined, '[^[:alpha:]]', '', 'g')) >= 6
       AND array_length(string_to_array(v_joined, ' '), 1) >= 2;
END;
$$;
GRANT EXECUTE ON FUNCTION public.quote_in_text(TEXT, TEXT) TO authenticated;


-- ------------------------------------------------------------
-- 1. meetings
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.meetings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id TEXT NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 200),
    occurred_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    created_by UUID DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE SET NULL,
    source_kind TEXT NOT NULL CHECK (source_kind IN ('text', 'audio')),
    -- Set only by the database (transcript insert -> 'transcribed', persist_meeting_run -> 'ready').
    status TEXT NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft', 'uploaded', 'transcribing', 'transcribed', 'analyzing', 'ready', 'failed')),
    language_hint TEXT CHECK (language_hint IN ('cs', 'en')),
    current_revision TEXT,
    -- { "S1": "Petr Novák" }: names are entered by people; the AI never names speakers.
    speaker_names JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(speaker_names) = 'object'),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    UNIQUE (id, project_id)
);
CREATE INDEX IF NOT EXISTS idx_meetings_project_occurred ON public.meetings (project_id, occurred_at DESC);

DROP TRIGGER IF EXISTS meetings_touch ON public.meetings;
CREATE TRIGGER meetings_touch BEFORE UPDATE ON public.meetings
    FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

-- project_id and created_by never change (a meeting cannot be moved to another project).
CREATE OR REPLACE FUNCTION public.guard_meeting_identity()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
    IF NEW.project_id IS DISTINCT FROM OLD.project_id OR NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.source_kind IS DISTINCT FROM OLD.source_kind THEN
        RAISE EXCEPTION 'Projekt, autora ani typ zdroje porady nelze měnit.' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.guard_meeting_identity() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS meetings_guard_identity ON public.meetings;
CREATE TRIGGER meetings_guard_identity BEFORE UPDATE ON public.meetings
    FOR EACH ROW EXECUTE FUNCTION public.guard_meeting_identity();

ALTER TABLE public.meetings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Members read meetings" ON public.meetings;
CREATE POLICY "Members read meetings" ON public.meetings FOR SELECT TO authenticated
    USING (public.is_project_member(project_id));
DROP POLICY IF EXISTS "Members create meetings" ON public.meetings;
CREATE POLICY "Members create meetings" ON public.meetings FOR INSERT TO authenticated
    WITH CHECK (public.is_project_member(project_id) AND created_by = auth.uid());
DROP POLICY IF EXISTS "Members edit meetings" ON public.meetings;
CREATE POLICY "Members edit meetings" ON public.meetings FOR UPDATE TO authenticated
    USING (public.is_project_member(project_id)) WITH CHECK (public.is_project_member(project_id));
DROP POLICY IF EXISTS "Creator or owner deletes meetings" ON public.meetings;
CREATE POLICY "Creator or owner deletes meetings" ON public.meetings FOR DELETE TO authenticated
    USING (public.is_project_member(project_id) AND (created_by = auth.uid() OR public.is_project_owner(project_id)));

REVOKE ALL ON public.meetings FROM PUBLIC, anon, authenticated;
GRANT SELECT, DELETE ON public.meetings TO authenticated;
GRANT INSERT (id, project_id, title, occurred_at, created_by, source_kind, language_hint, speaker_names)
    ON public.meetings TO authenticated;
GRANT UPDATE (title, occurred_at, language_hint, speaker_names) ON public.meetings TO authenticated;
GRANT ALL ON public.meetings TO service_role;

-- ------------------------------------------------------------
-- 2. meeting_transcripts (immutable revisions; shape follows UMC umc.transcript 1.0, see ARCHITECTURE §9.6)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.meeting_transcripts (
    meeting_id UUID NOT NULL,
    project_id TEXT NOT NULL,
    revision TEXT NOT NULL CHECK (revision ~ '^[0-9a-f]{64}$'),
    contract_version TEXT NOT NULL DEFAULT '1.0' CHECK (char_length(contract_version) <= 16),
    source TEXT NOT NULL CHECK (source IN ('paste', 'txt', 'md', 'vtt', 'srt', 'soniox')),
    speakers JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(speakers) = 'array'),
    segments JSONB NOT NULL CHECK (jsonb_typeof(segments) = 'array' AND jsonb_array_length(segments) BETWEEN 1 AND 20000),
    coverage JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(coverage) = 'object'),
    char_count INTEGER NOT NULL CHECK (char_count BETWEEN 1 AND 400000),
    created_by UUID DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    PRIMARY KEY (meeting_id, revision),
    FOREIGN KEY (meeting_id, project_id) REFERENCES public.meetings (id, project_id) ON DELETE CASCADE
);

-- Segment ids must be unique non-empty strings with non-empty text; total text bounded (400k characters, UMC eligibility).
CREATE OR REPLACE FUNCTION public.validate_meeting_transcript()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
    v_bad INTEGER;
    v_distinct INTEGER;
    v_total BIGINT;
BEGIN
    SELECT count(*) INTO v_bad
    FROM jsonb_array_elements(NEW.segments) s
    WHERE jsonb_typeof(s) <> 'object'
       OR jsonb_typeof(s -> 'id') IS DISTINCT FROM 'string'
       OR char_length(s ->> 'id') NOT BETWEEN 1 AND 200
       OR (s ->> 'id') ~ '[\s\]\[#]'
       OR jsonb_typeof(s -> 'text') IS DISTINCT FROM 'string'
       OR char_length(btrim(s ->> 'text')) = 0;
    IF v_bad > 0 THEN
        RAISE EXCEPTION 'Přepis obsahuje neplatné segmenty.' USING ERRCODE = '22023';
    END IF;
    SELECT count(DISTINCT s ->> 'id'), coalesce(sum(char_length(s ->> 'text')), 0)
      INTO v_distinct, v_total FROM jsonb_array_elements(NEW.segments) s;
    IF v_distinct <> jsonb_array_length(NEW.segments) THEN
        RAISE EXCEPTION 'Id segmentů přepisu musí být jedinečná.' USING ERRCODE = '22023';
    END IF;
    IF v_total > 400000 THEN
        RAISE EXCEPTION 'Přepis je příliš dlouhý (max 400 000 znaků).' USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.validate_meeting_transcript() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS meeting_transcripts_validate ON public.meeting_transcripts;
CREATE TRIGGER meeting_transcripts_validate BEFORE INSERT ON public.meeting_transcripts
    FOR EACH ROW EXECUTE FUNCTION public.validate_meeting_transcript();

-- A new transcript revision becomes the meeting's current one and moves it to 'transcribed' (the client never writes status).
CREATE OR REPLACE FUNCTION public.on_meeting_transcript_insert()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
    UPDATE public.meetings
       SET current_revision = NEW.revision,
           status = CASE WHEN status IN ('draft', 'uploaded', 'transcribing', 'failed', 'ready', 'analyzing') THEN 'transcribed' ELSE status END
     WHERE id = NEW.meeting_id AND project_id = NEW.project_id;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.on_meeting_transcript_insert() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS meeting_transcripts_after_insert ON public.meeting_transcripts;
CREATE TRIGGER meeting_transcripts_after_insert AFTER INSERT ON public.meeting_transcripts
    FOR EACH ROW EXECUTE FUNCTION public.on_meeting_transcript_insert();

ALTER TABLE public.meeting_transcripts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Members read transcripts" ON public.meeting_transcripts;
CREATE POLICY "Members read transcripts" ON public.meeting_transcripts FOR SELECT TO authenticated
    USING (public.is_project_member(project_id));
DROP POLICY IF EXISTS "Members add transcripts" ON public.meeting_transcripts;
CREATE POLICY "Members add transcripts" ON public.meeting_transcripts FOR INSERT TO authenticated
    WITH CHECK (public.is_project_member(project_id) AND created_by = auth.uid());

REVOKE ALL ON public.meeting_transcripts FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.meeting_transcripts TO authenticated;
GRANT INSERT (meeting_id, project_id, revision, contract_version, source, speakers, segments, coverage, char_count, created_by)
    ON public.meeting_transcripts TO authenticated;
GRANT ALL ON public.meeting_transcripts TO service_role;
-- Re-running this file AFTER migration 0600 must not drop the lineage column grants that file adds.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'meeting_transcripts' AND column_name = 'parent_revision') THEN
        GRANT INSERT (parent_revision, edit_note) ON public.meeting_transcripts TO authenticated;
    END IF;
END $$;

-- ------------------------------------------------------------
-- 3. intelligence_runs (one AI run = one validated output; project briefs and meeting briefs)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.intelligence_runs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id TEXT NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
    meeting_id UUID,
    kind TEXT NOT NULL CHECK (kind IN ('meeting_brief', 'project_brief')),
    status TEXT NOT NULL CHECK (status IN ('succeeded', 'failed')),
    transcript_revision TEXT,
    input_fingerprint TEXT NOT NULL CHECK (char_length(input_fingerprint) BETWEEN 1 AND 128),
    contract_version TEXT NOT NULL CHECK (char_length(contract_version) BETWEEN 1 AND 40),
    prompt_version TEXT NOT NULL CHECK (char_length(prompt_version) BETWEEN 1 AND 64),
    validator_version TEXT NOT NULL CHECK (char_length(validator_version) BETWEEN 1 AND 64),
    model TEXT CHECK (char_length(model) <= 100),
    ai_request_id UUID REFERENCES public.ai_requests(id) ON DELETE SET NULL,
    output JSONB CHECK (output IS NULL OR jsonb_typeof(output) = 'object'),
    rejected_count INTEGER NOT NULL DEFAULT 0 CHECK (rejected_count >= 0),
    error_code TEXT CHECK (char_length(error_code) <= 64),
    superseded_at TIMESTAMP WITH TIME ZONE,
    created_by UUID DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    UNIQUE (id, project_id),
    FOREIGN KEY (meeting_id, project_id) REFERENCES public.meetings (id, project_id) ON DELETE CASCADE,
    FOREIGN KEY (meeting_id, transcript_revision) REFERENCES public.meeting_transcripts (meeting_id, revision) ON DELETE CASCADE,
    CHECK ((kind = 'meeting_brief') = (meeting_id IS NOT NULL)),
    CHECK (kind <> 'meeting_brief' OR transcript_revision IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_runs_project_kind_created ON public.intelligence_runs (project_id, kind, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_runs_meeting_created ON public.intelligence_runs (meeting_id, created_at DESC);
-- Idempotency: at most one active succeeded run per (meeting, transcript revision, prompt version).
CREATE UNIQUE INDEX IF NOT EXISTS uq_runs_meeting_revision_prompt
    ON public.intelligence_runs (meeting_id, transcript_revision, prompt_version)
    WHERE kind = 'meeting_brief' AND status = 'succeeded' AND superseded_at IS NULL;

ALTER TABLE public.intelligence_runs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Members read runs" ON public.intelligence_runs;
CREATE POLICY "Members read runs" ON public.intelligence_runs FOR SELECT TO authenticated
    USING (public.is_project_member(project_id));
REVOKE ALL ON public.intelligence_runs FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.intelligence_runs TO authenticated;
GRANT ALL ON public.intelligence_runs TO service_role;

-- ------------------------------------------------------------
-- 4. intelligence_items (decisions, action items, risks... with evidence and a review state)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.intelligence_items (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id TEXT NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
    run_id UUID NOT NULL,
    meeting_id UUID,
    ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
    kind TEXT NOT NULL CHECK (kind IN ('decision', 'action_item', 'follow_up', 'risk', 'blocker', 'open_question')),
    text TEXT NOT NULL CHECK (char_length(btrim(text)) BETWEEN 1 AND 800),
    support TEXT NOT NULL CHECK (support IN ('linked', 'unverified')),
    -- Evidence[]: [{ref:'segment:<id>', quote, quoteFound, startMs, endMs}], 1..4 entries; validated by trigger.
    evidence JSONB NOT NULL,
    owner_text TEXT CHECK (char_length(owner_text) <= 100),
    due_text TEXT CHECK (char_length(due_text) <= 100),
    suggested_card_id TEXT,
    review_state TEXT NOT NULL DEFAULT 'proposed'
        CHECK (review_state IN ('proposed', 'accepted', 'rejected', 'applied', 'superseded')),
    -- Set ONLY by a human (review/apply RPCs); the AI never decides an assignee or a date.
    assignee_member_id TEXT REFERENCES public.workspace_members(id) ON DELETE SET NULL,
    due_date DATE,
    applied_card_id TEXT REFERENCES public.cards(id) ON DELETE SET NULL,
    applied_mode TEXT CHECK (applied_mode IN ('create_card', 'link_card', 'comment')),
    applied_at TIMESTAMP WITH TIME ZONE,
    decided_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
    decided_at TIMESTAMP WITH TIME ZONE,
    dedupe_key TEXT NOT NULL CHECK (dedupe_key ~ '^[0-9a-f]{64}$'),
    duplicate_of UUID REFERENCES public.intelligence_items(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    UNIQUE (run_id, ordinal),
    FOREIGN KEY (run_id, project_id) REFERENCES public.intelligence_runs (id, project_id) ON DELETE CASCADE,
    FOREIGN KEY (meeting_id, project_id) REFERENCES public.meetings (id, project_id) ON DELETE CASCADE,
    CHECK ((review_state = 'applied') = (applied_mode IS NOT NULL)),
    CHECK (review_state <> 'applied' OR applied_at IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_items_project_state_kind ON public.intelligence_items (project_id, review_state, kind);
CREATE INDEX IF NOT EXISTS idx_items_project_dedupe ON public.intelligence_items (project_id, dedupe_key);
CREATE INDEX IF NOT EXISTS idx_items_meeting ON public.intelligence_items (meeting_id, ordinal);

DROP TRIGGER IF EXISTS items_touch ON public.intelligence_items;
CREATE TRIGGER items_touch BEFORE UPDATE ON public.intelligence_items
    FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

-- INSERT guard: evidence must be a well-formed list of 1..4 references to REAL segments of the run's transcript revision,
-- and `linked` support needs at least one quote that the validator found. Defence in depth behind the persist RPC.
CREATE OR REPLACE FUNCTION public.validate_intelligence_item()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
    v_rev TEXT;
    v_segments JSONB;
    e JSONB;
    v_seg JSONB;
    v_ord INTEGER;
    v_next TEXT;
    v_quote TEXT;
    v_found BOOLEAN;
    v_out JSONB := '[]'::jsonb;
    v_any_linked BOOLEAN := FALSE;
BEGIN
    IF jsonb_typeof(NEW.evidence) <> 'array' OR jsonb_array_length(NEW.evidence) NOT BETWEEN 1 AND 4 THEN
        RAISE EXCEPTION 'Evidence musí obsahovat 1 až 4 odkazy.' USING ERRCODE = '22023';
    END IF;
    IF NEW.meeting_id IS NULL THEN
        RAISE EXCEPTION 'Položka porady musí odkazovat na poradu.' USING ERRCODE = '22023';
    END IF;
    SELECT r.transcript_revision INTO v_rev FROM public.intelligence_runs r WHERE r.id = NEW.run_id;
    SELECT t.segments INTO v_segments FROM public.meeting_transcripts t
     WHERE t.meeting_id = NEW.meeting_id AND t.revision = v_rev;
    IF v_segments IS NULL THEN
        RAISE EXCEPTION 'Přepis, na který se položka odvolává, neexistuje.' USING ERRCODE = '22023';
    END IF;
    -- The DATABASE is authoritative for evidence: `quoteFound` is recomputed from the stored transcript (a client can only
    -- DOWNGRADE: quoteFound stays true only if the caller said so AND the quote really is in the segment or in it plus the
    -- next one), times are taken from the segment, and `support` can never be higher than what the evidence proves.
    FOR e IN SELECT * FROM jsonb_array_elements(NEW.evidence) LOOP
        IF jsonb_typeof(e) <> 'object' OR jsonb_typeof(e -> 'ref') IS DISTINCT FROM 'string'
           OR (e ->> 'ref') !~ '^segment:[^\s\]\[#]{1,200}$' THEN
            RAISE EXCEPTION 'Neplatný odkaz na důkaz.' USING ERRCODE = '22023';
        END IF;
        v_seg := NULL;
        SELECT s.val, s.ord INTO v_seg, v_ord
          FROM jsonb_array_elements(v_segments) WITH ORDINALITY AS s(val, ord) WHERE s.val ->> 'id' = substr(e ->> 'ref', 9);
        IF v_seg IS NULL THEN
            RAISE EXCEPTION 'Důkaz odkazuje na neexistující segment přepisu (%).', e ->> 'ref' USING ERRCODE = '22023';
        END IF;
        v_quote := CASE WHEN jsonb_typeof(e -> 'quote') = 'string' THEN e ->> 'quote' ELSE NULL END;
        IF v_quote IS NOT NULL AND char_length(v_quote) > 200 THEN
            RAISE EXCEPTION 'Citace je příliš dlouhá (max 200 znaků).' USING ERRCODE = '22023';
        END IF;
        v_next := (v_segments -> v_ord::integer) ->> 'text'; -- 0-based index v_ord = the following segment (NULL at the end)
        v_found := (e -> 'quoteFound' = 'true'::jsonb)
                   AND v_quote IS NOT NULL
                   AND (public.quote_in_text(v_quote, v_seg ->> 'text')
                        OR (v_next IS NOT NULL AND public.quote_in_text(v_quote, (v_seg ->> 'text') || ' ' || v_next)));
        v_out := v_out || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
            'ref', e ->> 'ref', 'quote', v_quote, 'quoteFound', v_found,
            'startMs', v_seg -> 'startMs', 'endMs', v_seg -> 'endMs',
            'flag', CASE WHEN e ->> 'flag' = 'negation_nearby' THEN 'negation_nearby' ELSE NULL END)));
        IF v_found AND coalesce(e ->> 'flag', '') = '' THEN v_any_linked := TRUE; END IF;
    END LOOP;
    NEW.evidence := v_out;
    IF NEW.support = 'linked' AND NOT v_any_linked THEN
        NEW.support := 'unverified';
    END IF;
    IF NEW.kind IN ('decision', 'action_item') AND NEW.support <> 'linked' THEN
        -- 23514 (not 22023): persist_meeting_run skips such an item and counts it; every OTHER violation still aborts the whole run
        RAISE EXCEPTION 'Rozhodnutí a úkoly musí být podložené nalezenou citací.' USING ERRCODE = '23514';
    END IF;
    IF NEW.review_state <> 'proposed' THEN
        RAISE EXCEPTION 'Nová položka musí začít ve stavu "proposed".' USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.validate_intelligence_item() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS items_validate_insert ON public.intelligence_items;
CREATE TRIGGER items_validate_insert BEFORE INSERT ON public.intelligence_items
    FOR EACH ROW EXECUTE FUNCTION public.validate_intelligence_item();

-- UPDATE guard: the review state machine + immutability of everything the AI produced.
--   proposed -> accepted | rejected | superseded
--   accepted -> applied | rejected | superseded
--   rejected -> proposed (reopen) | superseded
--   applied  -> accepted (undo)
--   superseded: terminal
CREATE OR REPLACE FUNCTION public.guard_intelligence_item_update()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.project_id IS DISTINCT FROM OLD.project_id
       OR NEW.run_id IS DISTINCT FROM OLD.run_id OR NEW.meeting_id IS DISTINCT FROM OLD.meeting_id
       OR NEW.ordinal IS DISTINCT FROM OLD.ordinal OR NEW.kind IS DISTINCT FROM OLD.kind
       OR NEW.support IS DISTINCT FROM OLD.support OR NEW.evidence IS DISTINCT FROM OLD.evidence
       OR NEW.owner_text IS DISTINCT FROM OLD.owner_text OR NEW.due_text IS DISTINCT FROM OLD.due_text
       OR NEW.suggested_card_id IS DISTINCT FROM OLD.suggested_card_id OR NEW.dedupe_key IS DISTINCT FROM OLD.dedupe_key
       -- duplicate_of may only be CLEARED (ON DELETE SET NULL when the referenced item disappears)
       OR (NEW.duplicate_of IS DISTINCT FROM OLD.duplicate_of AND NEW.duplicate_of IS NOT NULL)
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'Výstup AI (typ, důkazy, podpora) nelze měnit.' USING ERRCODE = '42501';
    END IF;

    -- Only an APPLIED item may point at a card (an accepted/open one cannot carry a forged applied card).
    IF NEW.review_state <> 'applied' AND (NEW.applied_card_id IS NOT NULL OR NEW.applied_mode IS NOT NULL OR NEW.applied_at IS NOT NULL) THEN
        RAISE EXCEPTION 'Nepoužitá položka nesmí odkazovat na kartu.' USING ERRCODE = '55000';
    END IF;
    -- Who decided and when is set by the DATABASE on a state change; it cannot be written directly.
    IF NEW.review_state IS DISTINCT FROM OLD.review_state THEN
        IF auth.uid() IS NOT NULL THEN
            NEW.decided_by := auth.uid();
            NEW.decided_at := now();
        END IF;
    ELSIF (NEW.decided_by IS DISTINCT FROM OLD.decided_by AND NEW.decided_by IS NOT NULL)
          OR NEW.decided_at IS DISTINCT FROM OLD.decided_at THEN
        RAISE EXCEPTION 'Čas a autora rozhodnutí nelze měnit přímo.' USING ERRCODE = '42501';
    END IF;

    IF NEW.review_state = OLD.review_state THEN
        -- Edits of the human-controlled fields are only possible while the item is still open.
        -- (assignee / applied card may still be CLEARED: ON DELETE SET NULL of the member or card they point at)
        IF OLD.review_state NOT IN ('proposed', 'accepted')
           AND (NEW.text IS DISTINCT FROM OLD.text
                OR (NEW.assignee_member_id IS DISTINCT FROM OLD.assignee_member_id AND NEW.assignee_member_id IS NOT NULL)
                OR NEW.due_date IS DISTINCT FROM OLD.due_date
                OR (NEW.applied_card_id IS DISTINCT FROM OLD.applied_card_id AND NEW.applied_card_id IS NOT NULL)
                OR NEW.applied_mode IS DISTINCT FROM OLD.applied_mode OR NEW.applied_at IS DISTINCT FROM OLD.applied_at) THEN
            RAISE EXCEPTION 'Položku ve stavu "%" už nelze upravovat.', OLD.review_state USING ERRCODE = '55000';
        END IF;
        RETURN NEW;
    END IF;

    IF NOT ((OLD.review_state = 'proposed' AND NEW.review_state IN ('accepted', 'rejected', 'superseded'))
         OR (OLD.review_state = 'accepted' AND NEW.review_state IN ('applied', 'rejected', 'superseded'))
         OR (OLD.review_state = 'rejected' AND NEW.review_state IN ('proposed', 'superseded'))
         OR (OLD.review_state = 'applied' AND NEW.review_state = 'accepted')) THEN
        RAISE EXCEPTION 'Neplatný přechod stavu položky: % -> %.', OLD.review_state, NEW.review_state USING ERRCODE = '55000';
    END IF;

    IF NEW.review_state = 'applied' THEN
        IF NEW.applied_card_id IS NULL OR NEW.applied_mode IS NULL OR NEW.applied_at IS NULL THEN
            RAISE EXCEPTION 'Použitá položka musí odkazovat na kartu.' USING ERRCODE = '55000';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM public.cards c JOIN public.columns col ON col.id = c.column_id
                        WHERE c.id = NEW.applied_card_id AND col.project_id = OLD.project_id) THEN
            RAISE EXCEPTION 'Karta nepatří do projektu položky.' USING ERRCODE = '42501';
        END IF;
    ELSE
        IF NEW.applied_card_id IS NOT NULL OR NEW.applied_mode IS NOT NULL OR NEW.applied_at IS NOT NULL THEN
            RAISE EXCEPTION 'Nepoužitá položka nesmí odkazovat na kartu.' USING ERRCODE = '55000';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.guard_intelligence_item_update() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS items_guard_update ON public.intelligence_items;
CREATE TRIGGER items_guard_update BEFORE UPDATE ON public.intelligence_items
    FOR EACH ROW EXECUTE FUNCTION public.guard_intelligence_item_update();

ALTER TABLE public.intelligence_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Members read items" ON public.intelligence_items;
CREATE POLICY "Members read items" ON public.intelligence_items FOR SELECT TO authenticated
    USING (public.is_project_member(project_id));
DROP POLICY IF EXISTS "Members review items" ON public.intelligence_items;
CREATE POLICY "Members review items" ON public.intelligence_items FOR UPDATE TO authenticated
    USING (public.is_project_member(project_id)) WITH CHECK (public.is_project_member(project_id));
REVOKE ALL ON public.intelligence_items FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.intelligence_items TO authenticated;
GRANT UPDATE (review_state, text, assignee_member_id, due_date, applied_card_id, applied_mode, applied_at, decided_by, decided_at)
    ON public.intelligence_items TO authenticated;
GRANT ALL ON public.intelligence_items TO service_role;

-- ------------------------------------------------------------
-- 5. persist_meeting_run -- the ONLY way AI output enters the tables (atomic, idempotent, membership-checked)
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.persist_meeting_run(
    p_meeting_id UUID,
    p_run JSONB,
    p_items JSONB,
    p_force BOOLEAN DEFAULT FALSE
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_uid UUID := auth.uid();
    v_m public.meetings%ROWTYPE;
    v_status TEXT;
    v_rev TEXT;
    v_prompt TEXT;
    v_run_id UUID;
    v_old UUID;
    v_it JSONB;
    v_ord INTEGER;
    v_dedupe TEXT;
    v_dup UUID;
    v_suggested TEXT;
    v_skipped INTEGER := 0;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'Musíte být přihlášeni.' USING ERRCODE = '28000';
    END IF;
    IF p_run IS NULL OR jsonb_typeof(p_run) <> 'object' OR p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
        RAISE EXCEPTION 'Neplatný výstup AI.' USING ERRCODE = '22023';
    END IF;
    IF jsonb_array_length(p_items) > 300 THEN
        RAISE EXCEPTION 'Příliš mnoho položek.' USING ERRCODE = '22023';
    END IF;

    -- Authorization first (this function bypasses RLS, so the check is explicit). The row lock serializes
    -- concurrent persists for the same meeting.
    SELECT * INTO v_m FROM public.meetings WHERE id = p_meeting_id FOR UPDATE;
    IF NOT FOUND OR NOT public.is_project_member(v_m.project_id) THEN
        RAISE EXCEPTION 'Porada neexistuje nebo k ní nemáte přístup.' USING ERRCODE = '42501';
    END IF;

    v_status := coalesce(p_run ->> 'status', 'succeeded');
    v_rev := p_run ->> 'transcript_revision';
    v_prompt := p_run ->> 'prompt_version';
    IF v_status NOT IN ('succeeded', 'failed') OR v_rev IS NULL OR v_prompt IS NULL THEN
        RAISE EXCEPTION 'Neplatná metadata běhu AI.' USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.meeting_transcripts WHERE meeting_id = p_meeting_id AND revision = v_rev) THEN
        RAISE EXCEPTION 'Přepis (revize) neexistuje.' USING ERRCODE = '22023';
    END IF;
    IF v_status = 'failed' AND jsonb_array_length(p_items) > 0 THEN
        RAISE EXCEPTION 'Neúspěšný běh nesmí mít položky.' USING ERRCODE = '22023';
    END IF;
    -- the provenance link must be the caller's own ledger row of this feature (a client cannot attach someone else's request)
    IF nullif(p_run ->> 'ai_request_id', '') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.ai_requests r WHERE r.id = (p_run ->> 'ai_request_id')::uuid AND r.user_id = v_uid) THEN
        RAISE EXCEPTION 'Neplatný záznam o AI požadavku.' USING ERRCODE = '42501';
    END IF;

    IF v_status = 'succeeded' THEN
        -- Idempotency: the same transcript revision + prompt version is analysed once, unless re-run is forced.
        IF EXISTS (SELECT 1 FROM public.intelligence_runs r
                    WHERE r.meeting_id = p_meeting_id AND r.transcript_revision = v_rev AND r.prompt_version = v_prompt
                      AND r.kind = 'meeting_brief' AND r.status = 'succeeded' AND r.superseded_at IS NULL)
           AND NOT coalesce(p_force, FALSE) THEN
            RAISE EXCEPTION 'Tato verze přepisu už byla analyzována.' USING ERRCODE = '23505';
        END IF;
        -- Older active runs (any revision) are superseded. Only OPEN suggestions (proposed / rejected) are replaced by the
        -- new analysis; items a human ACCEPTED or APPLIED are approved project knowledge and are never touched here.
        -- A human withdraws an accepted item explicitly (review 'reject'); the duplicate hint on new items points at them.
        FOR v_old IN SELECT r.id FROM public.intelligence_runs r
                      WHERE r.meeting_id = p_meeting_id AND r.kind = 'meeting_brief' AND r.status = 'succeeded'
                        AND r.superseded_at IS NULL LOOP
            UPDATE public.intelligence_runs SET superseded_at = now() WHERE id = v_old;
            UPDATE public.intelligence_items SET review_state = 'superseded'
             WHERE run_id = v_old AND review_state IN ('proposed', 'rejected');
        END LOOP;
    END IF;

    INSERT INTO public.intelligence_runs
        (project_id, meeting_id, kind, status, transcript_revision, input_fingerprint, contract_version,
         prompt_version, validator_version, model, ai_request_id, output, rejected_count, error_code, created_by)
    VALUES
        (v_m.project_id, p_meeting_id, 'meeting_brief', v_status, v_rev,
         coalesce(p_run ->> 'input_fingerprint', ''), coalesce(p_run ->> 'contract_version', ''),
         v_prompt, coalesce(p_run ->> 'validator_version', ''), p_run ->> 'model',
         nullif(p_run ->> 'ai_request_id', '')::uuid, p_run -> 'output',
         coalesce((p_run ->> 'rejected_count')::integer, 0), p_run ->> 'error_code', v_uid)
    RETURNING id INTO v_run_id;

    v_ord := 0;
    FOR v_it IN SELECT * FROM jsonb_array_elements(p_items) LOOP
        v_dedupe := v_it ->> 'dedupe_key';
        v_suggested := nullif(v_it ->> 'suggested_card_id', '');
        IF v_suggested IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM public.cards c JOIN public.columns col ON col.id = c.column_id
             WHERE c.id = v_suggested AND col.project_id = v_m.project_id AND NOT c.archived) THEN
            RAISE EXCEPTION 'Navržená karta nepatří do tohoto projektu.' USING ERRCODE = '22023';
        END IF;
        -- Possible duplicate: an equivalent open/accepted/applied item of ANOTHER run in the same project.
        SELECT i.id INTO v_dup FROM public.intelligence_items i
         WHERE i.project_id = v_m.project_id AND i.dedupe_key = v_dedupe AND i.run_id <> v_run_id
           AND i.review_state IN ('proposed', 'accepted', 'applied')
         ORDER BY (i.review_state = 'applied') DESC, (i.review_state = 'accepted') DESC, i.created_at LIMIT 1;

        -- The item trigger recomputes the evidence from the stored transcript. An item the DATABASE cannot support (a decision or
        -- task whose quote is not really in the transcript) is skipped and counted, it does not fail the whole run.
        BEGIN
            INSERT INTO public.intelligence_items
                (project_id, run_id, meeting_id, ordinal, kind, text, support, evidence, owner_text, due_text,
                 suggested_card_id, dedupe_key, duplicate_of)
            VALUES
                (v_m.project_id, v_run_id, p_meeting_id, v_ord, v_it ->> 'kind', v_it ->> 'text', v_it ->> 'support',
                 v_it -> 'evidence', nullif(v_it ->> 'owner_text', ''), nullif(v_it ->> 'due_text', ''),
                 v_suggested, v_dedupe, v_dup);
            v_ord := v_ord + 1;
        EXCEPTION WHEN SQLSTATE '23514' THEN
            v_skipped := v_skipped + 1;
        END;
    END LOOP;
    IF v_skipped > 0 THEN
        UPDATE public.intelligence_runs SET rejected_count = rejected_count + v_skipped WHERE id = v_run_id;
    END IF;

    IF v_status = 'succeeded' THEN
        -- status only: the current revision is owned by the transcript trigger (analysing an OLDER revision must not rewind it)
        UPDATE public.meetings SET status = CASE WHEN current_revision = v_rev THEN 'ready' ELSE status END WHERE id = p_meeting_id;
    END IF;
    RETURN v_run_id;
END;
$$;

-- persist_project_brief: stores the validated Project Brief and marks the previous one superseded.
CREATE OR REPLACE FUNCTION public.persist_project_brief(p_project_id TEXT, p_run JSONB)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_uid UUID := auth.uid();
    v_status TEXT;
    v_id UUID;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'Musíte být přihlášeni.' USING ERRCODE = '28000';
    END IF;
    IF p_project_id IS NULL OR NOT public.is_project_member(p_project_id) THEN
        RAISE EXCEPTION 'K tomuto projektu nemáte přístup.' USING ERRCODE = '42501';
    END IF;
    IF p_run IS NULL OR jsonb_typeof(p_run) <> 'object' THEN
        RAISE EXCEPTION 'Neplatný výstup AI.' USING ERRCODE = '22023';
    END IF;
    v_status := coalesce(p_run ->> 'status', 'succeeded');
    IF v_status NOT IN ('succeeded', 'failed') THEN
        RAISE EXCEPTION 'Neplatný stav běhu AI.' USING ERRCODE = '22023';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('project_brief:' || p_project_id, 0));
    IF v_status = 'succeeded' THEN
        UPDATE public.intelligence_runs SET superseded_at = now()
         WHERE project_id = p_project_id AND kind = 'project_brief' AND status = 'succeeded' AND superseded_at IS NULL;
    END IF;
    INSERT INTO public.intelligence_runs
        (project_id, kind, status, input_fingerprint, contract_version, prompt_version, validator_version,
         model, ai_request_id, output, rejected_count, error_code, created_by)
    VALUES
        (p_project_id, 'project_brief', v_status, coalesce(p_run ->> 'input_fingerprint', ''),
         coalesce(p_run ->> 'contract_version', ''), coalesce(p_run ->> 'prompt_version', ''),
         coalesce(p_run ->> 'validator_version', ''), p_run ->> 'model', nullif(p_run ->> 'ai_request_id', '')::uuid,
         p_run -> 'output', coalesce((p_run ->> 'rejected_count')::integer, 0), p_run ->> 'error_code', v_uid)
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$$;

-- ------------------------------------------------------------
-- 6. Review / apply / undo (SECURITY INVOKER: RLS keeps applying to cards, comments and activity logs)
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.review_intelligence_item(p_item UUID, p_decision TEXT, p_edits JSONB DEFAULT '{}'::jsonb)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_it public.intelligence_items%ROWTYPE;
    v_new TEXT;
    v_text TEXT;
    v_member TEXT;
    v_due DATE;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Musíte být přihlášeni.' USING ERRCODE = '28000';
    END IF;
    IF p_decision NOT IN ('accept', 'reject', 'reopen') THEN
        RAISE EXCEPTION 'Neplatné rozhodnutí.' USING ERRCODE = '22023';
    END IF;
    p_edits := coalesce(p_edits, '{}'::jsonb);
    IF jsonb_typeof(p_edits) <> 'object' THEN
        RAISE EXCEPTION 'Neplatné úpravy.' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_it FROM public.intelligence_items WHERE id = p_item FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Položka neexistuje nebo k ní nemáte přístup.' USING ERRCODE = '42501';
    END IF;

    v_new := CASE p_decision WHEN 'accept' THEN 'accepted' WHEN 'reject' THEN 'rejected' ELSE 'proposed' END;
    -- Idempotent repeat of the same decision.
    IF v_it.review_state = v_new THEN
        RETURN jsonb_build_object('item_id', v_it.id, 'review_state', v_it.review_state, 'unchanged', TRUE);
    END IF;

    v_text := coalesce(nullif(btrim(p_edits ->> 'text'), ''), v_it.text);
    v_member := coalesce(nullif(p_edits ->> 'assignee_member_id', ''), v_it.assignee_member_id);
    IF nullif(p_edits ->> 'due_date', '') IS NOT NULL AND public.iso_date_or_null(p_edits ->> 'due_date') IS NULL THEN
        RAISE EXCEPTION 'Neplatné datum.' USING ERRCODE = '22023';
    END IF;
    v_due := coalesce(public.iso_date_or_null(p_edits ->> 'due_date'), v_it.due_date);

    UPDATE public.intelligence_items
       SET review_state = v_new, text = v_text, assignee_member_id = v_member, due_date = v_due,
           decided_by = auth.uid(), decided_at = now()
     WHERE id = p_item;
    RETURN jsonb_build_object('item_id', p_item, 'review_state', v_new, 'unchanged', FALSE);
END;
$$;

CREATE OR REPLACE FUNCTION public.apply_intelligence_item(p_item UUID, p_target JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_it public.intelligence_items%ROWTYPE;
    v_mode TEXT;
    v_card_id TEXT;
    v_col TEXT;
    v_title TEXT;
    v_details TEXT;
    v_due TEXT;
    v_member TEXT;
    v_mname TEXT; v_minit TEXT; v_mcolor TEXT;
    v_pos INTEGER;
    v_actor TEXT;
    v_quote TEXT;
    v_comment TEXT;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Musíte být přihlášeni.' USING ERRCODE = '28000';
    END IF;
    IF p_target IS NULL OR jsonb_typeof(p_target) <> 'object' THEN
        RAISE EXCEPTION 'Neplatný cíl.' USING ERRCODE = '22023';
    END IF;
    v_mode := p_target ->> 'mode';
    IF v_mode IS NULL OR v_mode NOT IN ('create_card', 'link_card', 'comment') THEN
        RAISE EXCEPTION 'Neplatný režim použití.' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_it FROM public.intelligence_items WHERE id = p_item FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Položka neexistuje nebo k ní nemáte přístup.' USING ERRCODE = '42501';
    END IF;

    -- Idempotency: a second apply returns the first result and writes nothing.
    IF v_it.review_state = 'applied' THEN
        RETURN jsonb_build_object('item_id', v_it.id, 'card_id', v_it.applied_card_id, 'mode', v_it.applied_mode,
                                  'already_applied', TRUE);
    END IF;
    IF v_it.review_state NOT IN ('proposed', 'accepted') THEN
        RAISE EXCEPTION 'Položku ve stavu "%" nelze použít.', v_it.review_state USING ERRCODE = '55000';
    END IF;

    SELECT coalesce(nullif(btrim(display_name), ''), email) INTO v_actor FROM public.profiles WHERE id = auth.uid();
    v_actor := coalesce(v_actor, 'uživatel');
    SELECT e ->> 'quote' INTO v_quote FROM jsonb_array_elements(v_it.evidence) e
     WHERE e -> 'quoteFound' = 'true'::jsonb LIMIT 1;

    IF v_mode = 'create_card' THEN
        IF v_it.kind NOT IN ('action_item', 'follow_up') THEN
            RAISE EXCEPTION 'Kartu lze vytvořit jen z úkolu nebo navazující akce.' USING ERRCODE = '22023';
        END IF;
        -- Duplicate prevention: an equivalent item was already turned into a card. Needs an explicit override.
        IF v_it.duplicate_of IS NOT NULL AND NOT coalesce((p_target ->> 'allow_duplicate')::boolean, FALSE)
           AND EXISTS (SELECT 1 FROM public.intelligence_items d WHERE d.id = v_it.duplicate_of AND d.review_state = 'applied') THEN
            RAISE EXCEPTION 'Stejný úkol už byl vytvořen z jiné porady.' USING ERRCODE = '23505';
        END IF;
        v_col := p_target ->> 'column_id';
        IF v_col IS NULL OR NOT EXISTS (SELECT 1 FROM public.columns WHERE id = v_col AND project_id = v_it.project_id) THEN
            RAISE EXCEPTION 'Sloupec nepatří do projektu položky.' USING ERRCODE = '42501';
        END IF;
        v_title := coalesce(nullif(btrim(p_target ->> 'title'), ''), left(v_it.text, 300));
        IF char_length(v_title) > 300 THEN
            RAISE EXCEPTION 'Název karty je příliš dlouhý.' USING ERRCODE = '22023';
        END IF;
        v_details := coalesce(p_target ->> 'details', '');
        IF char_length(v_details) > 8000 THEN
            RAISE EXCEPTION 'Popis karty je příliš dlouhý.' USING ERRCODE = '22023';
        END IF;
        v_due := coalesce(nullif(p_target ->> 'due_date', ''), v_it.due_date::text);
        IF v_due IS NOT NULL AND public.iso_date_or_null(v_due) IS NULL THEN
            RAISE EXCEPTION 'Neplatné datum.' USING ERRCODE = '22023';
        END IF;
        v_member := coalesce(nullif(p_target ->> 'assignee_member_id', ''), v_it.assignee_member_id);
        IF v_member IS NOT NULL THEN
            SELECT full_name, initials, avatar_color INTO v_mname, v_minit, v_mcolor
              FROM public.workspace_members WHERE id = v_member;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'Neznámý řešitel.' USING ERRCODE = '22023';
            END IF;
        END IF;

        SELECT coalesce(max(position), -1) + 1 INTO v_pos FROM public.cards WHERE column_id = v_col;
        v_card_id := 'card-' || replace(gen_random_uuid()::text, '-', '');
        INSERT INTO public.cards (id, column_id, title, details, due_date, position, assignee_name, assignee_initials, assignee_color)
        VALUES (v_card_id, v_col, v_title, v_details, v_due, v_pos, v_mname, v_minit, v_mcolor);
        IF v_member IS NOT NULL THEN
            INSERT INTO public.card_assignees (card_id, member_id, position) VALUES (v_card_id, v_member, 0);
        END IF;
        INSERT INTO public.activity_logs (id, project_id, card_id, actor_id, actor_name, action_type, entity_type, details)
        VALUES ('act-' || replace(gen_random_uuid()::text, '-', ''), v_it.project_id, v_card_id, auth.uid(), v_actor,
                'card_created', 'task',
                jsonb_build_object('title', v_title, 'source',
                    jsonb_build_object('type', 'intelligence_item', 'itemId', v_it.id, 'meetingId', v_it.meeting_id)));
    ELSE
        v_card_id := p_target ->> 'card_id';
        IF v_card_id IS NULL OR NOT EXISTS (
            SELECT 1 FROM public.cards c JOIN public.columns col ON col.id = c.column_id
             WHERE c.id = v_card_id AND col.project_id = v_it.project_id) THEN
            RAISE EXCEPTION 'Karta nepatří do projektu položky.' USING ERRCODE = '42501';
        END IF;
        IF v_mode = 'comment' OR coalesce((p_target ->> 'add_comment')::boolean, FALSE) THEN
            v_comment := left('Z porady: ' || v_it.text || coalesce(' («' || v_quote || '»)', ''), 4000);
            INSERT INTO public.task_comments (id, card_id, author_name, content)
            VALUES ('cm-' || replace(gen_random_uuid()::text, '-', ''), v_card_id, v_actor, v_comment);
        END IF;
    END IF;

    -- Applying straight from "proposed" is an implicit acceptance by the same human, recorded as such.
    IF v_it.review_state = 'proposed' THEN
        UPDATE public.intelligence_items SET review_state = 'accepted', decided_by = auth.uid(), decided_at = now()
         WHERE id = p_item;
    END IF;
    UPDATE public.intelligence_items
       SET review_state = 'applied', applied_card_id = v_card_id, applied_mode = v_mode, applied_at = now(),
           assignee_member_id = coalesce(v_member, assignee_member_id),
           due_date = coalesce(CASE WHEN v_due IS NULL THEN NULL ELSE v_due::date END, due_date),
           decided_by = coalesce(decided_by, auth.uid()), decided_at = coalesce(decided_at, now())
     WHERE id = p_item;
    RETURN jsonb_build_object('item_id', p_item, 'card_id', v_card_id, 'mode', v_mode, 'already_applied', FALSE);
END;
$$;

CREATE OR REPLACE FUNCTION public.undo_intelligence_item(p_item UUID, p_force BOOLEAN DEFAULT FALSE)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_it public.intelligence_items%ROWTYPE;
    v_card_updated TIMESTAMP WITH TIME ZONE;
    v_actor TEXT;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Musíte být přihlášeni.' USING ERRCODE = '28000';
    END IF;
    SELECT * INTO v_it FROM public.intelligence_items WHERE id = p_item FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Položka neexistuje nebo k ní nemáte přístup.' USING ERRCODE = '42501';
    END IF;
    IF v_it.review_state <> 'applied' THEN
        RETURN jsonb_build_object('item_id', v_it.id, 'review_state', v_it.review_state, 'unchanged', TRUE);
    END IF;

    IF v_it.applied_mode = 'create_card' AND v_it.applied_card_id IS NOT NULL THEN
        SELECT updated_at INTO v_card_updated FROM public.cards WHERE id = v_it.applied_card_id;
        IF FOUND THEN
            IF v_card_updated > v_it.applied_at AND NOT coalesce(p_force, FALSE) THEN
                RAISE EXCEPTION 'Karta byla od vytvoření změněna; vrácení vyžaduje potvrzení.' USING ERRCODE = '55000';
            END IF;
            -- Non-destructive: the card is archived, never deleted.
            UPDATE public.cards SET archived = TRUE, updated_at = now() WHERE id = v_it.applied_card_id;
            SELECT coalesce(nullif(btrim(display_name), ''), email) INTO v_actor FROM public.profiles WHERE id = auth.uid();
            INSERT INTO public.activity_logs (id, project_id, card_id, actor_id, actor_name, action_type, entity_type, details)
            VALUES ('act-' || replace(gen_random_uuid()::text, '-', ''), v_it.project_id, v_it.applied_card_id, auth.uid(),
                    coalesce(v_actor, 'uživatel'), 'card_archived', 'task',
                    jsonb_build_object('source', jsonb_build_object('type', 'intelligence_item_undo', 'itemId', v_it.id)));
        END IF;
    END IF;

    UPDATE public.intelligence_items
       SET review_state = 'accepted', applied_card_id = NULL, applied_mode = NULL, applied_at = NULL
     WHERE id = p_item;
    RETURN jsonb_build_object('item_id', p_item, 'review_state', 'accepted', 'unchanged', FALSE);
END;
$$;

-- ------------------------------------------------------------
-- 7. Privileges for the RPCs
-- ------------------------------------------------------------
REVOKE ALL ON FUNCTION public.persist_meeting_run(UUID, JSONB, JSONB, BOOLEAN) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.persist_project_brief(TEXT, JSONB) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.review_intelligence_item(UUID, TEXT, JSONB) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.apply_intelligence_item(UUID, JSONB) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.undo_intelligence_item(UUID, BOOLEAN) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.persist_meeting_run(UUID, JSONB, JSONB, BOOLEAN) TO authenticated;
GRANT EXECUTE ON FUNCTION public.persist_project_brief(TEXT, JSONB) TO authenticated;
GRANT EXECUTE ON FUNCTION public.review_intelligence_item(UUID, TEXT, JSONB) TO authenticated;
GRANT EXECUTE ON FUNCTION public.apply_intelligence_item(UUID, JSONB) TO authenticated;
GRANT EXECUTE ON FUNCTION public.undo_intelligence_item(UUID, BOOLEAN) TO authenticated;

INSERT INTO public.clearspace_migrations (version) VALUES ('20261118000500_intelligence_core')
ON CONFLICT (version) DO NOTHING;

-- ################################################################
-- ## verbatim copy of 20261118000600_intelligence_quality.sql
-- ################################################################
-- ============================================================
-- 20261118000600 -- Intelligence quality (R6): column roles, transcript revision lineage, meeting quotas,
--                   project freshness stamp
--
-- ADDITIVE and idempotent. Apply after 20261118000500_intelligence_core. No existing row is deleted; the only
-- data change is the one-time backfill of `columns.role` where it is still NULL.
--
--  * columns.role: explicit semantic role (todo / doing / review / done) so facts never depend on column NAMES alone.
--    NULL = "not set" (the app then falls back to the old name heuristic). Backfilled from names once.
--  * meeting_transcripts: `parent_revision` + `edit_note` + source 'edit' = a readable revision history; revisions stay
--    immutable. A per-meeting revision quota is enforced by a trigger.
--  * meetings: creation quota per project and per user per day (storage-abuse guard) enforced by a trigger.
--  * project_intelligence_stamp(project): one deterministic fingerprint of everything the Project Brief is derived from
--    (cards, comments, checklists, assignees, activity, accepted knowledge, transcript revisions). SECURITY INVOKER,
--    so RLS decides what the caller can count.
-- ============================================================

DO $$
BEGIN
    IF to_regclass('public.clearspace_migrations') IS NULL
       OR NOT EXISTS (SELECT 1 FROM public.clearspace_migrations WHERE version = '20261118000500_intelligence_core') THEN
        RAISE EXCEPTION 'Preflight failed -- apply 20261118000500_intelligence_core first. Nothing was changed.';
    END IF;
END $$;

-- ------------------------------------------------------------
-- 1. Column roles
-- ------------------------------------------------------------
ALTER TABLE public.columns ADD COLUMN IF NOT EXISTS role TEXT;
-- 'backfill' = guessed from the name by this migration; 'user' = chosen by a person (only 'user' counts as data worth protecting on rollback)
ALTER TABLE public.columns ADD COLUMN IF NOT EXISTS role_source TEXT;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'columns_role_check' AND conrelid = 'public.columns'::regclass) THEN
        ALTER TABLE public.columns
            ADD CONSTRAINT columns_role_check CHECK (role IS NULL OR role IN ('todo', 'doing', 'review', 'done'));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'columns_role_source_check' AND conrelid = 'public.columns'::regclass) THEN
        ALTER TABLE public.columns ADD CONSTRAINT columns_role_source_check CHECK (role_source IS NULL OR role_source IN ('backfill', 'user'));
    END IF;
END $$;

-- One-time backfill from names (only rows that have no role yet; never overwrites a human choice).
UPDATE public.columns SET role = CASE
        WHEN name ~* '(hotovo|done|dokon|complete)' THEN 'done'
        WHEN name ~* '(reviz|review|kontrol|testov)' THEN 'review'
        WHEN name ~* '(prob[ií]h|rozpracov|doing|progress|vývoj|vyvoj)' THEN 'doing'
        WHEN name ~* '(to ?do|k řešení|k reseni|backlog|nové|nove|plán)' THEN 'todo'
        ELSE NULL END,
    role_source = 'backfill'
 WHERE role IS NULL AND role_source IS NULL;

-- ------------------------------------------------------------
-- 2. Transcript revision lineage
-- ------------------------------------------------------------
ALTER TABLE public.meeting_transcripts ADD COLUMN IF NOT EXISTS parent_revision TEXT;
ALTER TABLE public.meeting_transcripts ADD COLUMN IF NOT EXISTS edit_note TEXT;

DO $$
DECLARE
    v_def TEXT;
BEGIN
    -- 'edit' = a human edited an earlier revision (new immutable revision, the parent stays readable).
    SELECT pg_get_constraintdef(oid) INTO v_def FROM pg_constraint
     WHERE conrelid = 'public.meeting_transcripts'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ILIKE '%source%paste%';
    IF v_def IS NOT NULL AND v_def NOT ILIKE '%''edit''%' THEN
        EXECUTE (SELECT format('ALTER TABLE public.meeting_transcripts DROP CONSTRAINT %I', conname) FROM pg_constraint
                  WHERE conrelid = 'public.meeting_transcripts'::regclass AND contype = 'c' AND pg_get_constraintdef(oid) ILIKE '%source%paste%' LIMIT 1);
        ALTER TABLE public.meeting_transcripts
            ADD CONSTRAINT meeting_transcripts_source_check CHECK (source IN ('paste', 'txt', 'md', 'vtt', 'srt', 'soniox', 'edit'));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'meeting_transcripts_edit_note_check') THEN
        ALTER TABLE public.meeting_transcripts
            ADD CONSTRAINT meeting_transcripts_edit_note_check CHECK (edit_note IS NULL OR char_length(edit_note) <= 500);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'meeting_transcripts_parent_fk') THEN
        ALTER TABLE public.meeting_transcripts
            ADD CONSTRAINT meeting_transcripts_parent_fk FOREIGN KEY (meeting_id, parent_revision)
            REFERENCES public.meeting_transcripts (meeting_id, revision) ON DELETE CASCADE;
    END IF;
END $$;

GRANT INSERT (parent_revision, edit_note) ON public.meeting_transcripts TO authenticated;

-- Limits live in ONE place so tests, docs and the app agree. (The audio migration 0700 uses the keys below; it does not redefine this
-- function, so re-running the migrations in any order leaves the same definition.)
CREATE OR REPLACE FUNCTION public.intelligence_limits()
RETURNS JSONB
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_temp
AS $$
    SELECT jsonb_build_object(
        'max_meetings_per_project', 500,
        'max_meetings_per_user_per_day', 40,
        'max_revisions_per_meeting', 25,
        'stt_attempts_per_meeting', 3,
        'audio_retention_days_default', 7,
        'audio_retention_days_max', 30,
        'max_audio_bytes', 52428800,
        'max_audio_ms', 18000000,
        'stt_stuck_minutes', 10,
        'stt_max_objects_per_meeting', 4
    );
$$;
GRANT EXECUTE ON FUNCTION public.intelligence_limits() TO authenticated;

-- Machine provenance token: a row for the CURRENT transaction id, written only by the server-trusted stt_complete (migration 0700,
-- which needs the server secret). Unlike a session setting (any member can SET app.*), a member cannot write this table
-- (no grants, RLS on, no policy), so a transcript with source 'soniox' cannot be forged from SQL either.
CREATE TABLE IF NOT EXISTS public.machine_persist_tokens (
    txid BIGINT PRIMARY KEY,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);
ALTER TABLE public.machine_persist_tokens ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.machine_persist_tokens FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.machine_persist_tokens TO service_role;

CREATE OR REPLACE FUNCTION public.validate_transcript_lineage()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_max INTEGER := (public.intelligence_limits() ->> 'max_revisions_per_meeting')::integer;
    v_machine BOOLEAN := EXISTS (SELECT 1 FROM public.machine_persist_tokens t WHERE t.txid = txid_current());
BEGIN
    -- machine provenance: only the server-trusted stt_complete (migration 0700) writes a token row for this transaction
    IF NEW.source = 'soniox' AND NOT v_machine THEN
        RAISE EXCEPTION 'Přepis ze strojového přepisu lze vytvořit jen přes stt_complete.' USING ERRCODE = '42501';
    END IF;
    IF NEW.source = 'edit' AND NEW.parent_revision IS NULL THEN
        RAISE EXCEPTION 'Úprava přepisu musí odkazovat na původní revizi.' USING ERRCODE = '22023';
    END IF;
    IF NEW.parent_revision IS NOT NULL AND NEW.parent_revision = NEW.revision THEN
        RAISE EXCEPTION 'Revize nemůže být svým vlastním předchůdcem.' USING ERRCODE = '22023';
    END IF;
    -- the revision cap never discards an already BILLED provider result
    IF NOT v_machine AND (SELECT count(*) FROM public.meeting_transcripts WHERE meeting_id = NEW.meeting_id) >= v_max THEN
        RAISE EXCEPTION 'Porada má maximální počet revizí přepisu (%).', v_max USING ERRCODE = 'PT429';
    END IF;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.validate_transcript_lineage() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS meeting_transcripts_lineage ON public.meeting_transcripts;
CREATE TRIGGER meeting_transcripts_lineage BEFORE INSERT ON public.meeting_transcripts
    FOR EACH ROW EXECUTE FUNCTION public.validate_transcript_lineage();

-- ------------------------------------------------------------
-- 3. Meeting creation quota
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.enforce_meeting_quota()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_lim JSONB := public.intelligence_limits();
BEGIN
    -- Serialise concurrent creates of the same project so the count cannot be raced past the limit.
    PERFORM pg_advisory_xact_lock(hashtextextended('meeting_quota:' || NEW.project_id, 0));
    IF NEW.created_by IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('meeting_quota_user:' || NEW.created_by::text, 0)); -- the per-day rule spans projects
    END IF;
    IF (SELECT count(*) FROM public.meetings WHERE project_id = NEW.project_id) >= (v_lim ->> 'max_meetings_per_project')::integer THEN
        RAISE EXCEPTION 'Projekt dosáhl maximálního počtu porad.' USING ERRCODE = 'PT429';
    END IF;
    IF NEW.created_by IS NOT NULL AND
       (SELECT count(*) FROM public.meetings WHERE created_by = NEW.created_by AND created_at > now() - interval '1 day')
         >= (v_lim ->> 'max_meetings_per_user_per_day')::integer THEN
        RAISE EXCEPTION 'Dosáhli jste denního limitu vytvořených porad.' USING ERRCODE = 'PT429';
    END IF;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.enforce_meeting_quota() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS meetings_quota ON public.meetings;
CREATE TRIGGER meetings_quota BEFORE INSERT ON public.meetings
    FOR EACH ROW EXECUTE FUNCTION public.enforce_meeting_quota();

-- ------------------------------------------------------------
-- 4. Project freshness stamp
-- ------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.project_intelligence_stamp(p_project_id TEXT)
RETURNS TEXT
LANGUAGE sql
STABLE
SET search_path = public, pg_temp
AS $$
    SELECT md5(concat_ws('|',
        'stamp-1',
        (SELECT concat_ws(',', count(*), count(*) FILTER (WHERE c.archived), coalesce(extract(epoch FROM max(c.updated_at))::text, ''))
           FROM public.cards c JOIN public.columns col ON col.id = c.column_id WHERE col.project_id = p_project_id),
        (SELECT coalesce(string_agg(col.id || ':' || col.position || ':' || coalesce(col.role, ''), ',' ORDER BY col.id), '')
           FROM public.columns col WHERE col.project_id = p_project_id),
        (SELECT concat_ws(',', count(*), coalesce(extract(epoch FROM max(tc.created_at))::text, ''))
           FROM public.task_comments tc JOIN public.cards c ON c.id = tc.card_id JOIN public.columns col ON col.id = c.column_id
          WHERE col.project_id = p_project_id),
        (SELECT concat_ws(',', count(*), count(*) FILTER (WHERE ch.completed))
           FROM public.task_checklists ch JOIN public.cards c ON c.id = ch.card_id JOIN public.columns col ON col.id = c.column_id
          WHERE col.project_id = p_project_id),
        (SELECT coalesce(md5(string_agg(ca.card_id || ':' || ca.member_id, ',' ORDER BY ca.card_id, ca.member_id)), '')
           FROM public.card_assignees ca JOIN public.cards c ON c.id = ca.card_id JOIN public.columns col ON col.id = c.column_id
          WHERE col.project_id = p_project_id),
        (SELECT concat_ws(',', count(*), coalesce(extract(epoch FROM max(a.created_at))::text, ''))
           FROM public.activity_logs a WHERE a.project_id = p_project_id),
        (SELECT concat_ws(',', count(*), coalesce(extract(epoch FROM max(i.decided_at))::text, ''))
           FROM public.intelligence_items i WHERE i.project_id = p_project_id AND i.review_state IN ('accepted', 'applied')),
        (SELECT coalesce(string_agg(m.id::text || ':' || coalesce(m.current_revision, ''), ',' ORDER BY m.id), '')
           FROM public.meetings m WHERE m.project_id = p_project_id)
    ));
$$;
REVOKE ALL ON FUNCTION public.project_intelligence_stamp(TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.project_intelligence_stamp(TEXT) TO authenticated;

INSERT INTO public.clearspace_migrations (version) VALUES ('20261118000600_intelligence_quality')
ON CONFLICT (version) DO NOTHING;

-- ################################################################
-- ## verbatim copy of 20261118000700_meeting_audio.sql
-- ################################################################
-- ============================================================
-- 20261118000700 -- Meeting audio (R5): consent, private Storage bucket, server-trusted Soniox transcription state machine
--
-- ADDITIVE and idempotent. Apply after 20261118000600_intelligence_quality. Safe to re-run in any order relative to 0500/0600
-- (it defines no function that another migration also defines).
--
-- Design (docs/intelligence/ARCHITECTURE.md §5, docs/intelligence/SONIOX_API_VERIFICATION.md, docs/intelligence/RELEASE_PLAN_R1_R7.md):
--  * Audio goes browser -> private bucket `meeting-audio` (path <project>/<meeting>/<uuid>.<ext>) under the caller's own RLS.
--    The Storage INSERT policy requires the meeting to carry a recorded CONSENT (an attestation by the member, not proof of
--    legal compliance) and caps the number of objects per meeting.
--  * No queue, no worker: the job lives in `meetings` + `stt_jobs` and advances only through SECURITY DEFINER RPCs that take a
--    row lock, so every LOCAL state transition is idempotent and a suspended serverless process cannot duplicate or lose it.
--    Remote provider billing is NOT exactly-once: Soniox offers no idempotency key for creating a transcription. The design
--    therefore never repeats a POST whose outcome is unknown, reconciles by `client_reference_id`, and keeps the estimate in
--    the budget until the outcome is known.
--  * TRUSTED BOOKKEEPING IS SERVER-ONLY. reserve / attach / complete / fail / unknown / cleanup RPCs require a server secret
--    (`require_server_secret`, a hash stored in `server_trust`, the plaintext only in the server environment), in addition to
--    the caller's own project membership. A project member calling them directly with their JWT is refused; budgets and
--    estimates are chosen by the server, never by a client. Until the owner registers a secret all of them refuse (fail closed).
--  * Money: a failure or cancellation never erases cost that may have been incurred (`ai_requests.billing_state`); a retry never
--    resets the per-meeting attempt counter; daily budgets sum everything that is not confirmed 'not_billed'.
--  * Provider data: every provider job is kept in `stt_jobs` (with its own retryable cleanup state) until deletion at the provider
--    is confirmed or abandoned after 8 tries; job rows outlive the meeting.
--  * Retention: `audio_delete_after` is set at UPLOAD (so abandoned/failed/cancelled audio has a deadline too). There is no cron;
--    deletion is performed by the server when a member opens the project's meetings or the meeting (sweep). Orphaned Storage
--    objects of deleted meetings are queued and members of the project may delete them.
-- ============================================================

DO $$
BEGIN
    IF to_regclass('public.clearspace_migrations') IS NULL
       OR NOT EXISTS (SELECT 1 FROM public.clearspace_migrations WHERE version = '20261118000600_intelligence_quality') THEN
        RAISE EXCEPTION 'Preflight failed -- apply 20261118000600_intelligence_quality first. Nothing was changed.';
    END IF;
    IF to_regclass('storage.buckets') IS NULL OR to_regclass('storage.objects') IS NULL
       OR to_regprocedure('storage.foldername(text)') IS NULL THEN
        RAISE EXCEPTION 'Preflight failed -- the Storage schema is not initialised. Nothing was changed.';
    END IF;
END $$;

-- ------------------------------------------------------------
-- 1. Ledger columns (usage, cost and billing certainty of audio)
-- ------------------------------------------------------------
ALTER TABLE public.ai_requests ADD COLUMN IF NOT EXISTS provider TEXT;
ALTER TABLE public.ai_requests ADD COLUMN IF NOT EXISTS audio_ms INTEGER;
ALTER TABLE public.ai_requests ADD COLUMN IF NOT EXISTS cost_usd NUMERIC(10, 4);
-- reserved = counted at the estimate; uncertain = provider outcome unknown (still counted); estimated = job exists, final length
-- unknown (counted); actual = provider reported the audio length; not_billed = CONFIRMED that nothing was billed (not counted)
ALTER TABLE public.ai_requests ADD COLUMN IF NOT EXISTS billing_state TEXT NOT NULL DEFAULT 'reserved';
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ai_requests_audio_ms_check') THEN
        ALTER TABLE public.ai_requests ADD CONSTRAINT ai_requests_audio_ms_check CHECK (audio_ms IS NULL OR audio_ms >= 0);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ai_requests_cost_usd_check') THEN
        ALTER TABLE public.ai_requests ADD CONSTRAINT ai_requests_cost_usd_check CHECK (cost_usd IS NULL OR cost_usd >= 0);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ai_requests_billing_state_check') THEN
        ALTER TABLE public.ai_requests ADD CONSTRAINT ai_requests_billing_state_check
            CHECK (billing_state IN ('reserved', 'uncertain', 'estimated', 'actual', 'not_billed'));
    END IF;
END $$;

-- ------------------------------------------------------------
-- 2. meetings: consent, audio object, STT state
-- ------------------------------------------------------------
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS consent_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS consent_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS audio_path TEXT;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS audio_bytes BIGINT;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS audio_mime TEXT;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS audio_client_ms INTEGER;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS audio_uploaded_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS audio_delete_after TIMESTAMP WITH TIME ZONE;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS audio_deleted_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_provider TEXT;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_model TEXT;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_job_id TEXT;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_state TEXT NOT NULL DEFAULT 'none';
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_attempts INTEGER NOT NULL DEFAULT 0;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_error_type TEXT;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_submitted_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_audio_ms INTEGER;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_cost_usd NUMERIC(10, 4);
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_request_id UUID REFERENCES public.ai_requests(id) ON DELETE SET NULL;
ALTER TABLE public.meetings ADD COLUMN IF NOT EXISTS stt_cleanup_pending BOOLEAN NOT NULL DEFAULT FALSE;

DO $$
BEGIN
    -- re-asserted on every run: an earlier version of this file created a narrower state list (no 'unknown')
    ALTER TABLE public.meetings DROP CONSTRAINT IF EXISTS meetings_stt_state_check;
    ALTER TABLE public.meetings ADD CONSTRAINT meetings_stt_state_check
        CHECK (stt_state IN ('none', 'submitting', 'unknown', 'transcribing', 'completed', 'failed'));
    ALTER TABLE public.meetings DROP CONSTRAINT IF EXISTS meetings_stt_misc_check;
    BEGIN
        ALTER TABLE public.meetings ADD CONSTRAINT meetings_stt_misc_check CHECK (
            stt_attempts BETWEEN 0 AND 10
            AND (stt_error_type IS NULL OR stt_error_type ~ '^[a-z0-9_]{1,64}$')
            AND (stt_job_id IS NULL OR char_length(stt_job_id) BETWEEN 1 AND 100)
            AND (audio_bytes IS NULL OR audio_bytes BETWEEN 1 AND 52428800)
            AND (audio_client_ms IS NULL OR audio_client_ms BETWEEN 0 AND 18000000));
    END;
END $$;
-- No new client privileges: consent, audio and STT columns are written only by the RPCs below.

-- ------------------------------------------------------------
-- 3. Server trust: the secret never lives in the repository or a client
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.server_trust (
    purpose TEXT PRIMARY KEY CHECK (purpose ~ '^[a-z_]{1,32}$'),
    secret_sha256 TEXT NOT NULL CHECK (secret_sha256 ~ '^[0-9a-f]{64}$'),
    rotated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);
ALTER TABLE public.server_trust ENABLE ROW LEVEL SECURITY; -- no policy: invisible through the API
REVOKE ALL ON public.server_trust FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.server_trust TO service_role;

CREATE OR REPLACE FUNCTION public.require_server_secret(p_purpose TEXT, p_secret TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
    IF p_secret IS NULL OR char_length(p_secret) < 32 OR NOT EXISTS (
        SELECT 1 FROM public.server_trust t
         WHERE t.purpose = p_purpose AND t.secret_sha256 = encode(sha256(convert_to(p_secret, 'UTF8')), 'hex')) THEN
        RAISE EXCEPTION 'Tato operace je vyhrazena serveru.' USING ERRCODE = '42501';
    END IF;
END;
$$;
REVOKE ALL ON FUNCTION public.require_server_secret(TEXT, TEXT) FROM PUBLIC, anon, authenticated;

-- ------------------------------------------------------------
-- 4. stt_jobs: every provider job, with its own retryable cleanup lifecycle (survives meeting/project deletion)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.stt_jobs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    meeting_id UUID REFERENCES public.meetings(id) ON DELETE SET NULL,
    project_id TEXT NOT NULL,
    user_id UUID,
    attempt INTEGER NOT NULL CHECK (attempt >= 1),
    -- sent to the provider as client_reference_id: lets an unknown outcome be reconciled by listing the provider's jobs
    client_reference TEXT NOT NULL CHECK (char_length(client_reference) <= 120),
    provider_job_id TEXT CHECK (provider_job_id IS NULL OR char_length(provider_job_id) BETWEEN 1 AND 100),
    request_id UUID REFERENCES public.ai_requests(id) ON DELETE SET NULL,
    est_audio_ms INTEGER,
    state TEXT NOT NULL CHECK (state IN ('submitting', 'unknown_outcome', 'active', 'succeeded', 'failed', 'cancelled')),
    cleanup_state TEXT NOT NULL DEFAULT 'not_needed' CHECK (cleanup_state IN ('not_needed', 'pending', 'done', 'abandoned')),
    cleanup_attempts INTEGER NOT NULL DEFAULT 0 CHECK (cleanup_attempts >= 0),
    cleanup_due_at TIMESTAMP WITH TIME ZONE,
    cleanup_last_error TEXT CHECK (cleanup_last_error IS NULL OR cleanup_last_error ~ '^[a-z0-9_]{1,64}$'),
    cleaned_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    UNIQUE (client_reference)
);
CREATE INDEX IF NOT EXISTS idx_stt_jobs_meeting ON public.stt_jobs (meeting_id);
CREATE INDEX IF NOT EXISTS idx_stt_jobs_cleanup ON public.stt_jobs (project_id, cleanup_state, cleanup_due_at);
ALTER TABLE public.stt_jobs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Members read stt jobs" ON public.stt_jobs;
CREATE POLICY "Members read stt jobs" ON public.stt_jobs FOR SELECT TO authenticated USING (public.is_project_member(project_id));
REVOKE ALL ON public.stt_jobs FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.stt_jobs TO authenticated;
GRANT ALL ON public.stt_jobs TO service_role;

-- ------------------------------------------------------------
-- 5. Private bucket + policies (insert requires consent and a per-meeting object cap)
-- ------------------------------------------------------------
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
    'meeting-audio', 'meeting-audio', false, 52428800,
    ARRAY['audio/mpeg', 'audio/mp4', 'audio/x-m4a', 'audio/m4a', 'audio/wav', 'audio/x-wav', 'audio/wave', 'audio/webm',
          'audio/ogg', 'audio/aac', 'audio/flac', 'audio/x-flac']
)
ON CONFLICT (id) DO UPDATE
   SET public = false,
       file_size_limit = EXCLUDED.file_size_limit,
       allowed_mime_types = EXCLUDED.allowed_mime_types;

-- Audio of a meeting that no longer exists (deleted directly or by cascade): kept so that members can still clean it up.
CREATE TABLE IF NOT EXISTS public.meeting_audio_orphans (
    path TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    queued_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);
ALTER TABLE public.meeting_audio_orphans ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Members read orphan audio" ON public.meeting_audio_orphans;
CREATE POLICY "Members read orphan audio" ON public.meeting_audio_orphans FOR SELECT TO authenticated USING (public.is_project_member(project_id));
DROP POLICY IF EXISTS "Members clear orphan audio" ON public.meeting_audio_orphans;
CREATE POLICY "Members clear orphan audio" ON public.meeting_audio_orphans FOR DELETE TO authenticated USING (public.is_project_member(project_id));
REVOKE ALL ON public.meeting_audio_orphans FROM PUBLIC, anon, authenticated;
GRANT SELECT, DELETE ON public.meeting_audio_orphans TO authenticated;
GRANT ALL ON public.meeting_audio_orphans TO service_role;

CREATE OR REPLACE FUNCTION public.queue_audio_orphan()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
    IF OLD.audio_path IS NOT NULL AND OLD.audio_deleted_at IS NULL THEN
        INSERT INTO public.meeting_audio_orphans (path, project_id) VALUES (OLD.audio_path, OLD.project_id) ON CONFLICT (path) DO NOTHING;
    END IF;
    RETURN OLD;
END;
$$;
REVOKE ALL ON FUNCTION public.queue_audio_orphan() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS meetings_queue_audio_orphan ON public.meetings;
CREATE TRIGGER meetings_queue_audio_orphan BEFORE DELETE ON public.meetings
    FOR EACH ROW EXECUTE FUNCTION public.queue_audio_orphan();

-- SECURITY INVOKER: evaluated under the caller's own RLS (a non-member cannot even see the meeting).
CREATE OR REPLACE FUNCTION public.can_access_meeting_audio(p_name TEXT, p_require_consent BOOLEAN DEFAULT FALSE)
RETURNS BOOLEAN
LANGUAGE sql STABLE
SET search_path = public, pg_temp
AS $$
    SELECT COALESCE(array_length(storage.foldername(p_name), 1) = 2, false)
       AND EXISTS (
            SELECT 1 FROM public.meetings m
             WHERE m.id::text = (storage.foldername(p_name))[2]
               AND m.project_id = (storage.foldername(p_name))[1]
               AND m.source_kind = 'audio'
               AND public.is_project_member(m.project_id)
               AND (NOT p_require_consent OR m.consent_at IS NOT NULL)
       );
$$;
REVOKE ALL ON FUNCTION public.can_access_meeting_audio(TEXT, BOOLEAN) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_access_meeting_audio(TEXT, BOOLEAN) TO authenticated;

-- An object whose meeting row is gone may be cleaned up by any member of the project named in its path.
CREATE OR REPLACE FUNCTION public.is_orphan_meeting_audio(p_name TEXT)
RETURNS BOOLEAN
LANGUAGE sql STABLE
SET search_path = public, pg_temp
AS $$
    SELECT COALESCE(array_length(storage.foldername(p_name), 1) = 2, false)
       AND public.is_project_member((storage.foldername(p_name))[1])
       AND NOT EXISTS (SELECT 1 FROM public.meetings m WHERE m.id::text = (storage.foldername(p_name))[2]);
$$;
REVOKE ALL ON FUNCTION public.is_orphan_meeting_audio(TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_orphan_meeting_audio(TEXT) TO authenticated;

-- How many objects already sit in this meeting's folder (counted through the caller's own storage RLS).
CREATE OR REPLACE FUNCTION public.meeting_audio_object_count(p_name TEXT)
RETURNS INTEGER
LANGUAGE sql STABLE
SET search_path = public, pg_temp
AS $$
    SELECT count(*)::integer FROM storage.objects o
     WHERE o.bucket_id = 'meeting-audio'
       AND o.name LIKE (array_to_string(storage.foldername(p_name), '/') || '/%');
$$;
REVOKE ALL ON FUNCTION public.meeting_audio_object_count(TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.meeting_audio_object_count(TEXT) TO authenticated;

-- Objects of a project's audio folder that are not the registered audio of any meeting: uploaded but never attached (tab closed
-- between upload and attach), or left behind by a failed delete. They carry no deadline in `meetings`, so the sweep removes them
-- after a grace period. With p_unattached_only = FALSE it lists EVERY object of the project (used before a project is deleted).
-- SECURITY INVOKER: only what the caller's own storage RLS lets them see.
CREATE OR REPLACE FUNCTION public.list_project_audio(p_project TEXT, p_unattached_only BOOLEAN DEFAULT TRUE, p_older_than_hours INTEGER DEFAULT 24)
RETURNS TABLE (path TEXT)
LANGUAGE sql STABLE
SET search_path = public, pg_temp
AS $$
    SELECT o.name
      FROM storage.objects o
     WHERE o.bucket_id = 'meeting-audio'
       AND public.is_project_member(p_project)
       AND starts_with(o.name, p_project || '/')
       AND o.created_at <= now() - make_interval(hours => greatest(coalesce(p_older_than_hours, 24), 0))
       AND (NOT p_unattached_only OR NOT EXISTS (SELECT 1 FROM public.meetings m WHERE m.audio_path = o.name))
     ORDER BY o.created_at
     LIMIT 500;
$$;
REVOKE ALL ON FUNCTION public.list_project_audio(TEXT, BOOLEAN, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.list_project_audio(TEXT, BOOLEAN, INTEGER) TO authenticated;

DROP POLICY IF EXISTS "meeting_audio_select" ON storage.objects;
CREATE POLICY "meeting_audio_select" ON storage.objects FOR SELECT TO authenticated
    USING (bucket_id = 'meeting-audio' AND (public.can_access_meeting_audio(name) OR public.is_orphan_meeting_audio(name)));
DROP POLICY IF EXISTS "meeting_audio_insert" ON storage.objects;
CREATE POLICY "meeting_audio_insert" ON storage.objects FOR INSERT TO authenticated
    WITH CHECK (bucket_id = 'meeting-audio' AND public.can_access_meeting_audio(name, TRUE)
                AND public.meeting_audio_object_count(name) < (public.intelligence_limits() ->> 'stt_max_objects_per_meeting')::integer);
DROP POLICY IF EXISTS "meeting_audio_delete" ON storage.objects;
CREATE POLICY "meeting_audio_delete" ON storage.objects FOR DELETE TO authenticated
    USING (bucket_id = 'meeting-audio' AND (public.can_access_meeting_audio(name) OR public.is_orphan_meeting_audio(name)));

-- ------------------------------------------------------------
-- 6. Member-level RPCs (the caller's own JWT and project membership; no server secret)
-- ------------------------------------------------------------
-- Locks the meeting row and proves membership. Every state-changing RPC starts here.
CREATE OR REPLACE FUNCTION public.lock_meeting_for_member(p_meeting UUID)
RETURNS public.meetings
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_m public.meetings%ROWTYPE;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Musíte být přihlášeni.' USING ERRCODE = '28000';
    END IF;
    SELECT * INTO v_m FROM public.meetings WHERE id = p_meeting FOR UPDATE;
    IF NOT FOUND OR NOT public.is_project_member(v_m.project_id) THEN
        RAISE EXCEPTION 'Porada neexistuje nebo k ní nemáte přístup.' USING ERRCODE = '42501';
    END IF;
    RETURN v_m;
END;
$$;
REVOKE ALL ON FUNCTION public.lock_meeting_for_member(UUID) FROM PUBLIC, anon, authenticated;

-- Consent is an ATTESTATION by the member that participants were informed. It is stored (who, when) and gates the upload;
-- it does not by itself establish legal compliance (see docs/intelligence/RELEASE_PLAN_R1_R7.md, external release gates).
CREATE OR REPLACE FUNCTION public.record_audio_consent(p_meeting UUID)
RETURNS TIMESTAMP WITH TIME ZONE
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_m public.meetings%ROWTYPE := public.lock_meeting_for_member(p_meeting);
BEGIN
    IF v_m.source_kind <> 'audio' THEN
        RAISE EXCEPTION 'Souhlas se zaznamenává jen u porady se zvukem.' USING ERRCODE = '22023';
    END IF;
    IF v_m.consent_at IS NOT NULL THEN
        RETURN v_m.consent_at; -- idempotent: the first consent stands
    END IF;
    UPDATE public.meetings SET consent_at = now(), consent_by = auth.uid() WHERE id = p_meeting RETURNING consent_at INTO v_m.consent_at;
    RETURN v_m.consent_at;
END;
$$;

-- Registers an uploaded object and starts its retention clock. Returns the PREVIOUS object path (if any) for deletion.
-- Does NOT reset the attempt counter or forget any provider job: replacing the file can never buy new attempts.
CREATE OR REPLACE FUNCTION public.attach_meeting_audio(p_meeting UUID, p_path TEXT, p_bytes BIGINT, p_mime TEXT, p_client_ms INTEGER DEFAULT NULL)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_m public.meetings%ROWTYPE := public.lock_meeting_for_member(p_meeting);
    v_lim JSONB := public.intelligence_limits();
    v_obj_size BIGINT;
    v_old TEXT;
BEGIN
    IF v_m.source_kind <> 'audio' THEN
        RAISE EXCEPTION 'Zvuk lze připojit jen k poradě se zvukem.' USING ERRCODE = '22023';
    END IF;
    IF v_m.consent_at IS NULL THEN
        RAISE EXCEPTION 'Bez zaznamenaného souhlasu účastníků nelze zvuk připojit.' USING ERRCODE = '55000';
    END IF;
    IF v_m.stt_state IN ('submitting', 'unknown', 'transcribing', 'completed') THEN
        RAISE EXCEPTION 'Zvuk teď nelze nahradit (přepis běží nebo je hotový).' USING ERRCODE = '55000';
    END IF;
    IF p_path IS NULL OR NOT starts_with(p_path, v_m.project_id || '/' || v_m.id::text || '/')
       OR substr(p_path, length(v_m.project_id || '/' || v_m.id::text || '/') + 1) !~ '^[0-9a-f-]{36}\.(mp3|m4a|mp4|wav|webm|ogg|aac|flac)$' THEN
        RAISE EXCEPTION 'Neplatná cesta souboru.' USING ERRCODE = '22023';
    END IF;
    IF p_mime IS NULL OR p_mime NOT IN (SELECT unnest(allowed_mime_types) FROM storage.buckets WHERE id = 'meeting-audio') THEN
        RAISE EXCEPTION 'Nepodporovaný typ zvuku.' USING ERRCODE = '22023';
    END IF;
    IF p_bytes IS NULL OR p_bytes NOT BETWEEN 1 AND (v_lim ->> 'max_audio_bytes')::bigint THEN
        RAISE EXCEPTION 'Neplatná velikost zvuku.' USING ERRCODE = '22023';
    END IF;
    IF p_client_ms IS NOT NULL AND p_client_ms NOT BETWEEN 0 AND (v_lim ->> 'max_audio_ms')::integer THEN
        RAISE EXCEPTION 'Zvuk je delší než povolený limit (300 minut).' USING ERRCODE = '22023';
    END IF;
    -- the object must really exist in the bucket (uploaded under the caller's RLS) and its size must match
    SELECT coalesce(nullif(o.metadata ->> 'size', '')::bigint, p_bytes) INTO v_obj_size
      FROM storage.objects o WHERE o.bucket_id = 'meeting-audio' AND o.name = p_path;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Soubor ve úložišti nebyl nalezen.' USING ERRCODE = '22023';
    END IF;
    IF v_obj_size <> p_bytes THEN
        RAISE EXCEPTION 'Velikost souboru nesouhlasí s úložištěm.' USING ERRCODE = '22023';
    END IF;

    v_old := CASE WHEN v_m.audio_deleted_at IS NULL AND v_m.audio_path IS DISTINCT FROM p_path THEN v_m.audio_path ELSE NULL END;
    UPDATE public.meetings
       SET audio_path = p_path, audio_bytes = p_bytes, audio_mime = p_mime, audio_client_ms = p_client_ms,
           audio_uploaded_at = now(), audio_deleted_at = NULL,
           audio_delete_after = now() + make_interval(days => (v_lim ->> 'audio_retention_days_default')::integer),
           stt_state = 'none', stt_error_type = NULL,
           status = CASE WHEN status IN ('draft', 'uploaded', 'failed') THEN 'uploaded' ELSE status END
     WHERE id = p_meeting;
    RETURN v_old;
END;
$$;

-- Marks the audio as deleted ONLY if the Storage object is really gone (the caller deletes it through the Storage API first).
CREATE OR REPLACE FUNCTION public.mark_audio_deleted(p_meeting UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_m public.meetings%ROWTYPE := public.lock_meeting_for_member(p_meeting);
BEGIN
    IF v_m.audio_path IS NULL THEN
        RETURN; -- nothing attached or already deleted (idempotent)
    END IF;
    IF v_m.stt_state IN ('submitting', 'unknown', 'transcribing') THEN
        RAISE EXCEPTION 'Zvuk nelze smazat, dokud přepis běží.' USING ERRCODE = '55000';
    END IF;
    IF EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'meeting-audio' AND o.name = v_m.audio_path) THEN
        RAISE EXCEPTION 'Soubor ve úložišti ještě existuje; nejprve ho smažte.' USING ERRCODE = '55000';
    END IF;
    UPDATE public.meetings SET audio_path = NULL, audio_deleted_at = now(), audio_delete_after = NULL WHERE id = p_meeting;
END;
$$;

-- ------------------------------------------------------------
-- 7. SERVER-TRUSTED RPCs (secret required in addition to membership)
-- ------------------------------------------------------------
-- Obsolete signatures. `CREATE OR REPLACE` with a different argument list creates a NEW overload and leaves the old function in
-- place, so the earlier secret-less versions (callable by any project member with their own budgets) must be dropped explicitly.
DROP FUNCTION IF EXISTS public.stt_reserve(UUID, INTEGER, BIGINT, BIGINT);
DROP FUNCTION IF EXISTS public.stt_attach_job(UUID, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.stt_fail(UUID, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.stt_complete(UUID, TEXT, TEXT, INTEGER, JSONB, INTEGER);
DROP FUNCTION IF EXISTS public.stt_mark_cleaned(UUID);
-- signatures of the previous (not attempt-bound) hardened version
DROP FUNCTION IF EXISTS public.stt_attach_job(TEXT, UUID, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.stt_mark_unknown(TEXT, UUID, TEXT);
DROP FUNCTION IF EXISTS public.stt_resolve_unknown(TEXT, UUID, TEXT);
DROP FUNCTION IF EXISTS public.stt_fail(TEXT, UUID, TEXT, TEXT, TEXT, INTEGER);

-- Starts a job (or reports why not). Estimate and budgets come from the SERVER. An unknown provider outcome is never repeated.
CREATE OR REPLACE FUNCTION public.stt_reserve(
    p_server_secret TEXT,
    p_meeting UUID,
    p_est_audio_ms INTEGER,
    p_user_daily_ms BIGINT,
    p_global_daily_ms BIGINT
)
RETURNS TABLE (outcome TEXT, request_id UUID, attempt INTEGER, audio_path TEXT, audio_mime TEXT, project_id TEXT, client_reference TEXT)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_uid UUID := auth.uid();
    v_m public.meetings%ROWTYPE;
    v_lim JSONB := public.intelligence_limits();
    v_used_user BIGINT;
    v_used_global BIGINT;
    v_id UUID;
    v_ref TEXT;
BEGIN
    PERFORM public.require_server_secret('stt', p_server_secret);
    v_m := public.lock_meeting_for_member(p_meeting);
    IF p_est_audio_ms IS NULL OR p_est_audio_ms NOT BETWEEN 1 AND (v_lim ->> 'max_audio_ms')::integer
       OR p_user_daily_ms IS NULL OR p_user_daily_ms < 1 OR p_global_daily_ms IS NULL OR p_global_daily_ms < 1 THEN
        RAISE EXCEPTION 'Neplatné parametry rezervace přepisu.' USING ERRCODE = '22023';
    END IF;
    IF v_m.source_kind <> 'audio' THEN
        RAISE EXCEPTION 'Přepis lze spustit jen u porady se zvukem.' USING ERRCODE = '22023';
    END IF;

    IF v_m.consent_at IS NULL THEN
        RETURN QUERY SELECT 'no_consent'::TEXT, NULL::UUID, v_m.stt_attempts, NULL::TEXT, NULL::TEXT, v_m.project_id, NULL::TEXT; RETURN;
    END IF;
    IF v_m.stt_state = 'completed' THEN
        RETURN QUERY SELECT 'already_done'::TEXT, v_m.stt_request_id, v_m.stt_attempts, NULL::TEXT, NULL::TEXT, v_m.project_id, NULL::TEXT; RETURN;
    END IF;
    IF v_m.audio_path IS NULL OR v_m.audio_deleted_at IS NOT NULL THEN
        RETURN QUERY SELECT 'no_audio'::TEXT, NULL::UUID, v_m.stt_attempts, NULL::TEXT, NULL::TEXT, v_m.project_id, NULL::TEXT; RETURN;
    END IF;
    -- A submission that has been 'submitting' for too long means the server died around the provider POST: the outcome is
    -- UNKNOWN (the job may exist and be billed). It is never silently redone; it moves to 'unknown' and is reconciled.
    IF v_m.stt_state = 'submitting' AND v_m.stt_submitted_at <= now() - make_interval(mins => (v_lim ->> 'stt_stuck_minutes')::integer) THEN
        UPDATE public.meetings SET stt_state = 'unknown', stt_error_type = 'outcome_unknown' WHERE id = p_meeting;
        UPDATE public.stt_jobs SET state = 'unknown_outcome', updated_at = now() WHERE meeting_id = p_meeting AND stt_jobs.attempt = v_m.stt_attempts AND stt_jobs.provider_job_id IS NULL;
        UPDATE public.ai_requests SET billing_state = 'uncertain' WHERE id = v_m.stt_request_id AND status = 'reserved';
        RETURN QUERY SELECT 'unknown_outcome'::TEXT, v_m.stt_request_id, v_m.stt_attempts, NULL::TEXT, NULL::TEXT, v_m.project_id, NULL::TEXT; RETURN;
    END IF;
    IF v_m.stt_state = 'unknown' THEN
        RETURN QUERY SELECT 'unknown_outcome'::TEXT, v_m.stt_request_id, v_m.stt_attempts, NULL::TEXT, NULL::TEXT, v_m.project_id, NULL::TEXT; RETURN;
    END IF;
    IF v_m.stt_state IN ('transcribing', 'submitting') THEN
        RETURN QUERY SELECT 'in_progress'::TEXT, v_m.stt_request_id, v_m.stt_attempts, NULL::TEXT, NULL::TEXT, v_m.project_id, NULL::TEXT; RETURN;
    END IF;
    -- cumulative per meeting: replacing the file or retrying never resets it
    IF v_m.stt_attempts >= (v_lim ->> 'stt_attempts_per_meeting')::integer THEN
        RETURN QUERY SELECT 'attempts_exhausted'::TEXT, NULL::UUID, v_m.stt_attempts, NULL::TEXT, NULL::TEXT, v_m.project_id, NULL::TEXT; RETURN;
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended('stt_reserve:user:' || v_uid::text, 0));
    PERFORM pg_advisory_xact_lock(hashtextextended('stt_reserve:global', 0));
    SELECT coalesce(sum(r.audio_ms), 0) INTO v_used_user FROM public.ai_requests r
     WHERE r.user_id = v_uid AND r.feature = 'meeting-transcribe' AND r.billing_state <> 'not_billed' AND r.created_at > now() - interval '24 hours';
    IF v_used_user + p_est_audio_ms > p_user_daily_ms THEN
        RETURN QUERY SELECT 'budget_exceeded'::TEXT, NULL::UUID, v_m.stt_attempts, NULL::TEXT, NULL::TEXT, v_m.project_id, NULL::TEXT; RETURN;
    END IF;
    SELECT coalesce(sum(r.audio_ms), 0) INTO v_used_global FROM public.ai_requests r
     WHERE r.feature = 'meeting-transcribe' AND r.billing_state <> 'not_billed' AND r.created_at > now() - interval '24 hours';
    IF v_used_global + p_est_audio_ms > p_global_daily_ms THEN
        RETURN QUERY SELECT 'global_budget_exceeded'::TEXT, NULL::UUID, v_m.stt_attempts, NULL::TEXT, NULL::TEXT, v_m.project_id, NULL::TEXT; RETURN;
    END IF;

    INSERT INTO public.ai_requests (user_id, project_id, feature, status, reserved_tokens, provider, audio_ms, billing_state)
    VALUES (v_uid, v_m.project_id, 'meeting-transcribe', 'reserved', 0, 'soniox', p_est_audio_ms, 'reserved')
    RETURNING public.ai_requests.id INTO v_id;
    v_ref := p_meeting::text || ':' || (v_m.stt_attempts + 1)::text;
    INSERT INTO public.stt_jobs (meeting_id, project_id, user_id, attempt, client_reference, request_id, est_audio_ms, state)
    VALUES (p_meeting, v_m.project_id, v_uid, v_m.stt_attempts + 1, v_ref, v_id, p_est_audio_ms, 'submitting');
    UPDATE public.meetings
       SET stt_state = 'submitting', stt_attempts = stt_attempts + 1, stt_submitted_at = now(), stt_request_id = v_id,
           stt_error_type = NULL, status = 'transcribing'
     WHERE id = p_meeting;
    RETURN QUERY SELECT 'started'::TEXT, v_id, v_m.stt_attempts + 1, v_m.audio_path, v_m.audio_mime, v_m.project_id, v_ref;
END;
$$;

-- Records the provider's job id for a SPECIFIC attempt (p_attempt comes from stt_reserve / the job's client_reference): a late
-- job id can therefore never attach to a newer attempt. If that attempt is no longer the live one (cancelled, abandoned, failed,
-- superseded) the id is STILL kept and queued for provider-side deletion ('orphaned'); the meeting's current attempt is untouched.
CREATE OR REPLACE FUNCTION public.stt_attach_job(p_server_secret TEXT, p_meeting UUID, p_attempt INTEGER, p_job_id TEXT, p_model TEXT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_m public.meetings%ROWTYPE;
    v_job public.stt_jobs%ROWTYPE;
    v_live BOOLEAN;
BEGIN
    PERFORM public.require_server_secret('stt', p_server_secret);
    v_m := public.lock_meeting_for_member(p_meeting);
    IF p_attempt IS NULL OR p_attempt < 1 OR p_job_id IS NULL OR char_length(p_job_id) NOT BETWEEN 1 AND 100
       OR p_model IS NULL OR char_length(p_model) NOT BETWEEN 1 AND 64 THEN
        RAISE EXCEPTION 'Neplatná data úlohy přepisu.' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_job FROM public.stt_jobs WHERE meeting_id = p_meeting AND attempt = p_attempt FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Úloha přepisu neexistuje.' USING ERRCODE = '55000';
    END IF;
    v_live := p_attempt = v_m.stt_attempts;
    IF v_job.provider_job_id IS NOT NULL AND v_job.provider_job_id <> p_job_id THEN
        RAISE EXCEPTION 'Tento pokus už má jinou úlohu u poskytovatele.' USING ERRCODE = '55000';
    END IF;
    IF v_job.provider_job_id = p_job_id THEN
        RETURN CASE WHEN v_live AND v_m.stt_state IN ('transcribing', 'completed') THEN 'attached' ELSE 'orphaned' END; -- idempotent
    END IF;
    IF v_live AND v_m.stt_state IN ('submitting', 'unknown') THEN
        UPDATE public.stt_jobs SET provider_job_id = p_job_id, state = 'active', updated_at = now() WHERE id = v_job.id;
        UPDATE public.meetings SET stt_job_id = p_job_id, stt_model = p_model, stt_provider = 'soniox', stt_state = 'transcribing', stt_error_type = NULL WHERE id = p_meeting;
        UPDATE public.ai_requests SET model = p_model, billing_state = 'reserved' WHERE id = v_m.stt_request_id AND status = 'reserved';
        RETURN 'attached';
    END IF;
    -- not the live attempt (or it was cancelled / failed while the POST was in flight): the job EXISTS and may be billed
    UPDATE public.stt_jobs SET provider_job_id = p_job_id, cleanup_state = 'pending', cleanup_due_at = now(), updated_at = now() WHERE id = v_job.id;
    UPDATE public.ai_requests SET model = p_model, billing_state = CASE WHEN billing_state IN ('reserved', 'uncertain') THEN 'estimated' ELSE billing_state END
     WHERE id = v_job.request_id;
    UPDATE public.meetings SET stt_cleanup_pending = TRUE WHERE id = p_meeting;
    RETURN 'orphaned';
END;
$$;

-- The provider POST ended in a way that does not tell whether the job was created (timeout, network, 5xx, unreadable 2xx body) or
-- the user cancelled while it was in flight. NEVER repeated automatically: the estimate stays in the budget and the outcome is
-- reconciled by client_reference_id. Bound to the attempt: a stale call for an older attempt changes nothing.
CREATE OR REPLACE FUNCTION public.stt_mark_unknown(p_server_secret TEXT, p_meeting UUID, p_attempt INTEGER, p_error_type TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_m public.meetings%ROWTYPE;
    v_type TEXT := CASE WHEN p_error_type ~ '^[a-z0-9_]{1,64}$' THEN p_error_type ELSE 'unknown' END;
BEGIN
    PERFORM public.require_server_secret('stt', p_server_secret);
    v_m := public.lock_meeting_for_member(p_meeting);
    IF p_attempt IS DISTINCT FROM v_m.stt_attempts OR v_m.stt_state <> 'submitting' THEN
        RETURN; -- idempotent / stale: nothing to mark
    END IF;
    UPDATE public.meetings SET stt_state = 'unknown', stt_error_type = v_type WHERE id = p_meeting;
    UPDATE public.stt_jobs SET state = 'unknown_outcome', updated_at = now() WHERE meeting_id = p_meeting AND attempt = p_attempt AND provider_job_id IS NULL;
    UPDATE public.ai_requests SET billing_state = 'uncertain' WHERE id = v_m.stt_request_id AND status = 'reserved';
END;
$$;

-- Ends an unknown outcome. 'absent' = the provider's job list proved that no job exists (nothing billed, retry is safe).
-- 'abandon' = the user gave up waiting: the estimate STAYS in the budget (the job may still exist). Neither is allowed before the
-- submission window (stt_stuck_minutes) has passed, so a POST that is still in flight can never be followed by a second paid one.
-- Returns 'resolved', 'too_early' or 'noop'.
CREATE OR REPLACE FUNCTION public.stt_resolve_unknown(p_server_secret TEXT, p_meeting UUID, p_resolution TEXT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_m public.meetings%ROWTYPE;
BEGIN
    PERFORM public.require_server_secret('stt', p_server_secret);
    v_m := public.lock_meeting_for_member(p_meeting);
    IF p_resolution NOT IN ('absent', 'abandon') THEN
        RAISE EXCEPTION 'Neplatné vyřešení nejistého stavu.' USING ERRCODE = '22023';
    END IF;
    IF v_m.stt_state <> 'unknown' THEN
        RETURN 'noop'; -- idempotent: nothing to resolve
    END IF;
    IF v_m.stt_submitted_at > now() - make_interval(mins => (public.intelligence_limits() ->> 'stt_stuck_minutes')::integer) THEN
        RETURN 'too_early';
    END IF;
    UPDATE public.meetings
       SET stt_state = 'failed', status = 'failed', stt_error_type = CASE WHEN p_resolution = 'absent' THEN 'not_created' ELSE 'outcome_unknown' END
     WHERE id = p_meeting;
    UPDATE public.stt_jobs
       SET state = 'failed', cleanup_state = CASE WHEN p_resolution = 'absent' THEN 'not_needed' ELSE 'abandoned' END, updated_at = now()
     WHERE meeting_id = p_meeting AND attempt = v_m.stt_attempts AND provider_job_id IS NULL;
    IF p_resolution = 'absent' THEN
        UPDATE public.ai_requests SET status = 'failed', error_code = 'not_created', completed_at = now(), audio_ms = 0, cost_usd = 0, billing_state = 'not_billed'
         WHERE id = v_m.stt_request_id AND status = 'reserved';
    ELSE
        UPDATE public.ai_requests SET status = 'failed', error_code = 'outcome_unknown', completed_at = now()
         WHERE id = v_m.stt_request_id AND status = 'reserved'; -- billing_state stays 'uncertain', the estimate keeps counting
    END IF;
    RETURN 'resolved';
END;
$$;

-- Records a failure of ONE attempt. p_billing says what we KNOW about cost: 'none' (confirmed nothing billed), 'uncertain',
-- 'estimated' (a job exists and may have run: the reserved estimate stays), 'actual' (provider reported p_audio_ms). A failure or
-- a cancellation therefore never erases cost that may have been incurred. A stale call for an older attempt changes nothing.
CREATE OR REPLACE FUNCTION public.stt_fail(p_server_secret TEXT, p_meeting UUID, p_attempt INTEGER, p_job_id TEXT, p_error_type TEXT, p_billing TEXT, p_audio_ms INTEGER DEFAULT NULL)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_m public.meetings%ROWTYPE;
    v_type TEXT := CASE WHEN p_error_type ~ '^[a-z0-9_]{1,64}$' THEN p_error_type ELSE 'unknown' END;
    v_job public.stt_jobs%ROWTYPE;
    v_pid TEXT;
    v_ms INTEGER;
BEGIN
    PERFORM public.require_server_secret('stt', p_server_secret);
    v_m := public.lock_meeting_for_member(p_meeting);
    IF p_billing NOT IN ('none', 'uncertain', 'estimated', 'actual') THEN
        RAISE EXCEPTION 'Neplatný stav účtování.' USING ERRCODE = '22023';
    END IF;
    IF p_attempt IS DISTINCT FROM v_m.stt_attempts THEN
        RETURN; -- stale call for another attempt: never touches the live one
    END IF;
    IF v_m.stt_state = 'failed' THEN
        RETURN; -- idempotent
    END IF;
    IF v_m.stt_state NOT IN ('submitting', 'transcribing') THEN
        RAISE EXCEPTION 'Přepis neběží, není co označit jako selhaný.' USING ERRCODE = '55000';
    END IF;
    -- An attempt that is still SUBMITTING may have a paid POST in flight (or one whose answer was lost). Anything but a CONFIRMED
    -- 'none' (the provider rejected the request) must NOT become a plain failure, because a failed attempt can be retried at once
    -- and that would be a second paid POST. Such a call (a cancellation, a timeout) leaves the outcome UNKNOWN instead.
    IF v_m.stt_state = 'submitting' AND p_billing <> 'none' THEN
        UPDATE public.meetings SET stt_state = 'unknown', stt_error_type = v_type WHERE id = p_meeting;
        UPDATE public.stt_jobs SET state = 'unknown_outcome', updated_at = now() WHERE meeting_id = p_meeting AND attempt = p_attempt AND provider_job_id IS NULL;
        UPDATE public.ai_requests SET billing_state = 'uncertain' WHERE id = v_m.stt_request_id AND status = 'reserved';
        RETURN;
    END IF;
    SELECT * INTO v_job FROM public.stt_jobs WHERE meeting_id = p_meeting AND attempt = p_attempt FOR UPDATE;
    v_pid := coalesce(v_job.provider_job_id, p_job_id); -- NOT v_m.stt_job_id: that may be a PREVIOUS attempt's id
    IF p_job_id IS NOT NULL AND v_job.provider_job_id IS NOT NULL AND v_job.provider_job_id <> p_job_id THEN
        RAISE EXCEPTION 'Úloha přepisu nesouhlasí.' USING ERRCODE = '55000';
    END IF;
    UPDATE public.stt_jobs
       SET provider_job_id = v_pid, state = CASE WHEN v_type = 'cancelled' THEN 'cancelled' ELSE 'failed' END,
           cleanup_state = CASE WHEN v_pid IS NULL THEN 'not_needed' ELSE 'pending' END,
           cleanup_due_at = CASE WHEN v_pid IS NULL THEN NULL ELSE now() END, updated_at = now()
     WHERE id = v_job.id;
    UPDATE public.meetings
       SET stt_state = 'failed', stt_error_type = v_type, status = 'failed', stt_job_id = coalesce(v_pid, stt_job_id),
           stt_cleanup_pending = (v_pid IS NOT NULL) OR stt_cleanup_pending
     WHERE id = p_meeting;
    IF p_billing = 'none' THEN
        UPDATE public.ai_requests SET status = 'failed', error_code = v_type, completed_at = now(), audio_ms = 0, cost_usd = 0, billing_state = 'not_billed'
         WHERE id = v_m.stt_request_id AND status = 'reserved';
    ELSE
        v_ms := CASE WHEN p_billing = 'actual' THEN least(greatest(coalesce(p_audio_ms, 0), 0), (public.intelligence_limits() ->> 'max_audio_ms')::integer) ELSE NULL END;
        UPDATE public.ai_requests
           SET status = 'failed', error_code = v_type, completed_at = now(), billing_state = p_billing,
               audio_ms = coalesce(v_ms, audio_ms), cost_usd = round(coalesce(v_ms, audio_ms)::numeric / 3600000.0 * 0.10, 4)
         WHERE id = v_m.stt_request_id AND status = 'reserved';
    END IF;
END;
$$;

-- Stores the normalised transcript as a revision (source 'soniox') and books the real audio duration and cost.
CREATE OR REPLACE FUNCTION public.stt_complete(
    p_server_secret TEXT,
    p_meeting UUID,
    p_job_id TEXT,
    p_model TEXT,
    p_audio_ms INTEGER,
    p_transcript JSONB,
    p_retention_days INTEGER DEFAULT 7
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_m public.meetings%ROWTYPE;
    v_lim JSONB := public.intelligence_limits();
    v_rev TEXT := p_transcript ->> 'revision';
    v_cost NUMERIC(10, 4);
    v_days INTEGER := least(greatest(coalesce(p_retention_days, 7), 1), (v_lim ->> 'audio_retention_days_max')::integer);
BEGIN
    PERFORM public.require_server_secret('stt', p_server_secret);
    v_m := public.lock_meeting_for_member(p_meeting);
    IF v_m.stt_state = 'completed' AND v_m.stt_job_id = p_job_id THEN
        RETURN v_m.current_revision; -- idempotent: the same job is stored once
    END IF;
    IF v_m.stt_state <> 'transcribing' OR v_m.stt_job_id IS DISTINCT FROM p_job_id THEN
        RAISE EXCEPTION 'Úloha přepisu nesouhlasí nebo neběží.' USING ERRCODE = '55000';
    END IF;
    IF p_audio_ms IS NULL OR p_audio_ms NOT BETWEEN 0 AND (v_lim ->> 'max_audio_ms')::integer
       OR v_rev IS NULL OR v_rev !~ '^[0-9a-f]{64}$' OR jsonb_typeof(p_transcript -> 'segments') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'Neplatný přepis.' USING ERRCODE = '22023';
    END IF;

    -- machine provenance token for THIS transaction (checked by validate_transcript_lineage; members cannot write this table)
    INSERT INTO public.machine_persist_tokens (txid) VALUES (txid_current()) ON CONFLICT (txid) DO NOTHING;
    INSERT INTO public.meeting_transcripts (meeting_id, project_id, revision, source, speakers, segments, coverage, char_count, created_by)
    VALUES (p_meeting, v_m.project_id, v_rev, 'soniox',
            coalesce(p_transcript -> 'speakers', '[]'::jsonb), p_transcript -> 'segments', coalesce(p_transcript -> 'coverage', '{}'::jsonb),
            (p_transcript ->> 'char_count')::integer, auth.uid())
    ON CONFLICT (meeting_id, revision) DO NOTHING;
    DELETE FROM public.machine_persist_tokens WHERE txid = txid_current();

    v_cost := round(p_audio_ms::numeric / 3600000.0 * 0.10, 4); -- estimate: US$0.10 per audio hour (verified 2026-11-18)
    UPDATE public.meetings
       SET stt_state = 'completed', stt_audio_ms = p_audio_ms, stt_cost_usd = v_cost, stt_error_type = NULL, stt_model = p_model,
           stt_cleanup_pending = TRUE,
           -- the deadline set at upload is never extended
           audio_delete_after = least(coalesce(audio_delete_after, now() + make_interval(days => v_days)), now() + make_interval(days => v_days)),
           current_revision = v_rev, status = 'transcribed'
     WHERE id = p_meeting;
    UPDATE public.stt_jobs SET state = 'succeeded', cleanup_state = 'pending', cleanup_due_at = now(), updated_at = now()
     WHERE meeting_id = p_meeting AND provider_job_id = p_job_id;
    UPDATE public.ai_requests
       SET status = 'succeeded', model = p_model, audio_ms = p_audio_ms, cost_usd = v_cost, completed_at = now(), billing_state = 'actual'
     WHERE id = v_m.stt_request_id;
    RETURN v_rev;
END;
$$;

-- Result of a provider-side deletion attempt. 'retry' backs off (2^n minutes, max 24 h) and gives up after 8 tries
-- (the provider deletes everything after 30 days anyway). The job row, and with it the provider job id, outlives the meeting.
CREATE OR REPLACE FUNCTION public.stt_cleanup_result(p_server_secret TEXT, p_job UUID, p_result TEXT, p_error_type TEXT DEFAULT NULL)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_job public.stt_jobs%ROWTYPE;
    v_err TEXT := CASE WHEN p_error_type ~ '^[a-z0-9_]{1,64}$' THEN p_error_type ELSE NULL END;
BEGIN
    PERFORM public.require_server_secret('stt', p_server_secret);
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Musíte být přihlášeni.' USING ERRCODE = '28000';
    END IF;
    IF p_result NOT IN ('done', 'retry', 'abandon') THEN
        RAISE EXCEPTION 'Neplatný výsledek úklidu.' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_job FROM public.stt_jobs WHERE id = p_job FOR UPDATE;
    IF NOT FOUND OR NOT public.is_project_member(v_job.project_id) THEN
        RAISE EXCEPTION 'Úloha neexistuje nebo k ní nemáte přístup.' USING ERRCODE = '42501';
    END IF;
    IF v_job.cleanup_state IN ('done', 'abandoned') THEN
        RETURN; -- idempotent
    END IF;
    IF p_result = 'done' THEN
        UPDATE public.stt_jobs SET cleanup_state = 'done', cleaned_at = now(), cleanup_last_error = NULL, updated_at = now() WHERE id = p_job;
    ELSIF p_result = 'abandon' OR v_job.cleanup_attempts + 1 >= 8 THEN
        UPDATE public.stt_jobs SET cleanup_state = 'abandoned', cleanup_attempts = cleanup_attempts + 1, cleanup_last_error = v_err, updated_at = now() WHERE id = p_job;
    ELSE
        UPDATE public.stt_jobs
           SET cleanup_attempts = cleanup_attempts + 1, cleanup_last_error = v_err,
               cleanup_due_at = now() + make_interval(mins => least(power(2, cleanup_attempts + 1)::integer, 1440)), updated_at = now()
         WHERE id = p_job;
    END IF;
    IF v_job.meeting_id IS NOT NULL THEN
        UPDATE public.meetings SET stt_cleanup_pending = EXISTS (
            SELECT 1 FROM public.stt_jobs j WHERE j.meeting_id = v_job.meeting_id AND j.cleanup_state = 'pending')
         WHERE id = v_job.meeting_id;
    END IF;
END;
$$;

DO $$
DECLARE
    f TEXT;
BEGIN
    FOREACH f IN ARRAY ARRAY[
        'record_audio_consent(uuid)', 'attach_meeting_audio(uuid,text,bigint,text,integer)', 'mark_audio_deleted(uuid)',
        'stt_reserve(text,uuid,integer,bigint,bigint)', 'stt_attach_job(text,uuid,integer,text,text)', 'stt_mark_unknown(text,uuid,integer,text)',
        'stt_resolve_unknown(text,uuid,text)', 'stt_fail(text,uuid,integer,text,text,text,integer)',
        'stt_complete(text,uuid,text,text,integer,jsonb,integer)', 'stt_cleanup_result(text,uuid,text,text)']
    LOOP
        EXECUTE format('REVOKE ALL ON FUNCTION public.%s FROM PUBLIC, anon', f);
        EXECUTE format('GRANT EXECUTE ON FUNCTION public.%s TO authenticated', f);
    END LOOP;
END $$;

INSERT INTO public.clearspace_migrations (version) VALUES ('20261118000700_meeting_audio')
ON CONFLICT (version) DO NOTHING;

-- ################################################################
-- ## data repair for installations that ran an earlier version (no-op on a current database)
-- ################################################################
-- (a) an attempt that exists on the meeting but has no stt_jobs row (earlier version): give it one. The earlier version sent the bare
--     meeting id as client_reference_id, so that is what the row carries (reconciliation lists by it).
INSERT INTO public.stt_jobs (meeting_id, project_id, user_id, attempt, client_reference, provider_job_id, request_id, est_audio_ms, state, cleanup_state, cleanup_due_at)
SELECT m.id, m.project_id, m.created_by, m.stt_attempts, m.id::text,
       CASE WHEN m.stt_state IN ('transcribing', 'completed') OR m.stt_cleanup_pending THEN m.stt_job_id END,
       m.stt_request_id, r.audio_ms,
       CASE m.stt_state WHEN 'completed' THEN 'succeeded' WHEN 'transcribing' THEN 'active' WHEN 'failed' THEN 'failed' ELSE 'submitting' END,
       CASE WHEN m.stt_job_id IS NOT NULL AND m.stt_cleanup_pending THEN 'pending' ELSE 'not_needed' END,
       CASE WHEN m.stt_job_id IS NOT NULL AND m.stt_cleanup_pending THEN now() END
  FROM public.meetings m
  LEFT JOIN public.ai_requests r ON r.id = m.stt_request_id
 WHERE m.stt_attempts > 0
   AND NOT EXISTS (SELECT 1 FROM public.stt_jobs j WHERE j.meeting_id = m.id)
ON CONFLICT (client_reference) DO NOTHING;

-- (b) audio with no deletion deadline (earlier version set it only at completion): the deadline runs from the upload
UPDATE public.meetings
   SET audio_delete_after = coalesce(audio_uploaded_at, now()) + make_interval(days => (public.intelligence_limits() ->> 'audio_retention_days_default')::integer)
 WHERE audio_path IS NOT NULL AND audio_deleted_at IS NULL AND audio_delete_after IS NULL;

-- (c) ledger certainty of finished transcriptions
UPDATE public.ai_requests SET billing_state = 'actual'
 WHERE feature = 'meeting-transcribe' AND status = 'succeeded' AND billing_state = 'reserved';

INSERT INTO public.clearspace_migrations (version) VALUES ('20261118000800_stt_stabilization_repair')
ON CONFLICT (version) DO NOTHING;
-- ################################################################
-- ## supersession: guard_meeting_identity() exactly as in 20261118000900_meeting_creator_erasure.sql
-- ################################################################
CREATE OR REPLACE FUNCTION public.guard_meeting_identity()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
    IF NEW.project_id IS DISTINCT FROM OLD.project_id OR NEW.source_kind IS DISTINCT FROM OLD.source_kind THEN
        RAISE EXCEPTION 'Projekt, autora ani typ zdroje porady nelze měnit.' USING ERRCODE = '42501';
    END IF;
    IF NEW.created_by IS DISTINCT FROM OLD.created_by THEN
        -- the only legitimate change: ON DELETE SET NULL after the author's profile has been deleted (account erasure)
        IF NOT (OLD.created_by IS NOT NULL AND NEW.created_by IS NULL
                AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = OLD.created_by)) THEN
            RAISE EXCEPTION 'Projekt, autora ani typ zdroje porady nelze měnit.' USING ERRCODE = '42501';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION public.guard_meeting_identity() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS meetings_guard_identity ON public.meetings;
CREATE TRIGGER meetings_guard_identity BEFORE UPDATE ON public.meetings
    FOR EACH ROW EXECUTE FUNCTION public.guard_meeting_identity();
